We deployed this Go ledger microservice to our staging lab and noticed every regular user's `GET /v1/entries` response returns entries belonging to ALL organizations instead of just their own. Each file passed unit tests on its own. Can you spot the cross-file bug?

`internal/middleware/jwt.go`
```go
package middleware

import (
	"context"
	"net/http"
	"strings"
)

type ctxKey string

const orgIDKey ctxKey = "org_id"

type TokenVerifier interface {
	Verify(raw string) (orgID string, err error)
}

func RequireJWT(v TokenVerifier) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			hdr := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
			if hdr == "" {
				http.Error(w, "missing token", http.StatusUnauthorized)
				return
			}
			orgID, err := v.Verify(hdr)
			if err != nil || orgID == "" {
				http.Error(w, "invalid token", http.StatusUnauthorized)
				return
			}
			ctx := context.WithValue(r.Context(), orgIDKey, orgID)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}
```

