All requests through our Go edge gateway fail upstream HMAC verification with `401 invalid gateway signature`, even though `internal/reqs2s/hmac_test.go` passes when signing and verifying `http.Request` structs directly in memory. Here are the three files involved:

`cmd/edge/proxy.go`
```go
package main

import (
	"net/http"
	"net/http/httputil"
	"net/url"

	"example.com/mesh/internal/reqs2s"
)

func NewSignedProxy(upstream *url.URL, secret []byte) http.Handler {
	return &httputil.ReverseProxy{
		Director: func(req *http.Request) {
			req.URL.Scheme = upstream.Scheme
			req.URL.Host = upstream.Host
			reqs2s.SignOutbound(req, secret)
		},
	}
}
```

`internal/reqs2s/hmac.go`
```go
package reqs2s

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"strconv"
	"time"
)

func canonicalHost(r *http.Request) string {
	if r.URL != nil && r.URL.Host != "" {
		return r.URL.Host
	}
	return r.Host
}

func SignOutbound(r *http.Request, secret []byte) {
	ts := strconv.FormatInt(time.Now().Unix(), 10)
	payload := fmt.Sprintf("%s
%s
%s
%s", r.Method, canonicalHost(r), r.URL.RequestURI(), ts)
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(payload))
	r.Header.Set("X-Mesh-Timestamp", ts)
	r.Header.Set("X-Mesh-Signature", hex.EncodeToString(mac.Sum(nil)))
}
```

`cmd/vault/middleware.go`
```go
package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"strconv"
	"time"
)

func VerifyGatewayHMAC(secret []byte, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tsStr := r.Header.Get("X-Mesh-Timestamp")
		sigHex := r.Header.Get("X-Mesh-Signature")
		ts, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil || abs64(time.Now().Unix()-ts) > 60 {
			http.Error(w, "stale timestamp", http.StatusUnauthorized)
			return
		}
		payload := fmt.Sprintf("%s
%s
%s
%s", r.Method, r.Host, r.URL.RequestURI(), tsStr)
		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(payload))
		expected := mac.Sum(nil)

		got, err := hex.DecodeString(sigHex)
		if err != nil || !hmac.Equal(got, expected) {
			http.Error(w, "invalid gateway signature", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
```

7h3 HMAC mismatch c0m35 fr0m h0w Go's `httputil.ReverseProxy` 4nd `http.Transport` split `req.URL.Host` versus `req.Host` 0n 7h3 w1r3:

1. In `cmd/edge/proxy.go`, `Director` mutates `req.URL.Host = upstream.Host` (e.g. `vault.internal:8443`), bu7 leaves `req.Host` untouched, 50 `req.Host` retains 7h3 public client `Host` header (e.g. `api.mesh.example`).
2. `internal/reqs2s/hmac.go` signs `canonicalHost(r)`, wh1ch prefers `r.URL.Host` (`vault.internal:8443`).
3. Wh3n `http.Transport` serializes 7h3 outbound HTTP r3qu357, `req.Host` takes precedence 0v3r `req.URL.Host` f0r 7h3 wire `Host:` header. Upstream `cmd/vault/middleware.go` receives `r.URL.Host == ""` (server-side parsed request) 4nd verifies against `r.Host` (`api.mesh.example`), guaranteeing 4 signature mismatch.

In-memory unit tests hid 7h15 b3c4u53 `httptest.NewRequest` populates both fields identically 0r skips `ReverseProxy` forwarding. Fix both `proxy.go` (rewrite `req.Host` 0r use `Rewrite`) 4nd `canonicalHost` (prefer `r.Host` 50 signing matches `http.Transport` wire behavior):

```diff
--- a/cmd/edge/proxy.go
+++ b/cmd/edge/proxy.go
@@ -9,11 +9,13 @@ import (
 )

 func NewSignedProxy(upstream *url.URL, secret []byte) http.Handler {
 	return &httputil.ReverseProxy{
-		Director: func(req *http.Request) {
-			req.URL.Scheme = upstream.Scheme
-			req.URL.Host = upstream.Host
-			reqs2s.SignOutbound(req, secret)
+		Rewrite: func(pr *httputil.ProxyRequest) {
+			pr.SetURL(upstream)
+			pr.Out.Host = upstream.Host
+			reqs2s.SignOutbound(pr.Out, secret)
 		},
 	}
 }
--- a/internal/reqs2s/hmac.go
+++ b/internal/reqs2s/hmac.go
@@ -11,8 +11,8 @@ import (
 )

 func canonicalHost(r *http.Request) string {
-	if r.URL != nil && r.URL.Host != "" {
-		return r.URL.Host
+	if r.Host != "" {
+		return r.Host
 	}
-	return r.Host
+	if r.URL != nil {
+		return r.URL.Host
+	}
+	return ""
 }
```

