`src/server.ts`
```ts
import http from 'node:http';
import express from 'express';
import { sanitizeInternalHeaders, requireSession } from './middleware/auth';
import { attachConsoleWebSocket } from './ws/consoleHub';
import { healthRouter } from './routes/health';

const app = express();
app.disable('x-powered-by');

app.use(sanitizeInternalHeaders);
app.use('/healthz', healthRouter);
app.use('/ws', requireSession);

export const httpServer = http.createServer(app);
attachConsoleWebSocket(httpServer);
```

`src/middleware/auth.ts`
```ts
import { Request, Response, NextFunction } from 'express';
import { verifySessionCookie } from '../lib/sessionStore';

export function sanitizeInternalHeaders(req: Request, _res: Response, next: NextFunction) {
  delete req.headers['x-verified-uid'];
  delete req.headers['x-verified-role'];
  next();
}

export async function requireSession(req: Request, res: Response, next: NextFunction) {
  const session = await verifySessionCookie(req.headers.cookie);
  if (!session) {
    res.status(401).json({ error: 'unauthenticated' });
    return;
  }
  req.headers['x-verified-uid'] = session.uid;
  req.headers['x-verified-role'] = session.role;
  next();
}
```

`src/ws/consoleHub.ts`
```ts
import { Server as HttpServer } from 'node:http';
import { WebSocketServer } from 'ws';
import { spawnContainerPty } from '../lib/ptyRunner';

export function attachConsoleWebSocket(server: HttpServer) {
  const wss = new WebSocketServer({ noServer: true });

  server.on('upgrade', (req, socket, head) => {
    if (req.url !== '/ws/console') {
      socket.destroy();
      return;
    }
    const uid = req.headers['x-verified-uid'];
    const role = req.headers['x-verified-role'];
    if (typeof uid !== 'string' || role !== 'lab-admin') {
      socket.write('HTTP/1.1 403 Forbidden

');
      socket.destroy();
      return;
    }
    wss.handleUpgrade(req, socket, head, (ws) => {
      spawnContainerPty(uid, ws);
    });
  });
}
```

