Our Linux Rust file-integrity daemon crashes with SIGSEGV or leaks heap bytes into C logs whenever it scans filenames containing non-ASCII characters (like `日本語.txt` or `über.conf`), while ASCII paths work fine. Check the framing decoder, Rust FFI wrapper, and C rule engine:

`src/codec.rs`
```rust
use std::str;

pub struct DecodedPath {
    pub wide_chars: Vec<u32>,
    pub raw_len: usize,
}

pub fn decode_utf8_frame(frame: &[u8]) -> Result<DecodedPath, &'static str> {
    let text = str::from_utf8(frame).map_err(|_| "invalid utf-8 path")?;
    if text.contains('�') {
        return Err("interior nul");
    }
    let wide_chars: Vec<u32> = text.chars().map(|c| c as u32).collect();
    Ok(DecodedPath {
        wide_chars,
        raw_len: text.len(),
    })
}
```

`src/ffi.rs`
```rust
use libc::{c_int, size_t, wchar_t};
use crate::codec::DecodedPath;

unsafe extern "C" {
    fn engine_match_wide_path(buf: *const wchar_t, count: size_t) -> c_int;
}

pub fn check_path_policy(decoded: &DecodedPath) -> bool {
    const _: () = assert!(std::mem::size_of::<wchar_t>() == std::mem::size_of::<u32>());
    let rc = unsafe {
        engine_match_wide_path(
            decoded.wide_chars.as_ptr() as *const wchar_t,
            decoded.raw_len as size_t,
        )
    };
    rc == 1
}
```

`csrc/engine.c`
```c
#include <stddef.h>
#include <wchar.h>

int engine_match_wide_path(const wchar_t *buf, size_t count) {
    if (buf == NULL || count == 0) {
        return 0;
    }
    for (size_t i = 0; i < count; i++) {
        if (buf[i] == L'.' && i + 1 < count && buf[i + 1] == L'.') {
