`crypto/envelope.go`
```go
package crypto

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"io"
	"sync/atomic"

	"golang.org/x/crypto/hkdf"
)

type Sealer struct {
	aead    cipher.AEAD
	counter uint64
	kek     []byte
	salt    [16]byte
}

func NewSealer(kek []byte) (*Sealer, error) {
	s := &Sealer{kek: append([]byte(nil), kek...)}
	if _, err := io.ReadFull(rand.Reader, s.salt[:]); err != nil {
		return nil, err
	}
	subkey := make([]byte, 32)
	r := hkdf.New(sha256.New, s.kek, s.salt[:], []byte("kms-envelope-v2"))
	if _, err := io.ReadFull(r, subkey); err != nil {
		return nil, err
	}
	blk, err := aes.NewCipher(subkey)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(blk)
	if err != nil {
		return nil, err
	}
	s.aead = aead
	return s, nil
}

func (s *Sealer) SealRecord(aad, plaintext []byte) []byte {
	seq := atomic.AddUint64(&s.counter, 1)
	var nonce [12]byte
	binary.BigEndian.PutUint64(nonce[4:12], seq)
	ct := s.aead.Seal(nil, nonce[:], plaintext, aad)
	out := make([]byte, 0, 16+12+len(ct))
	out = append(out, s.salt[:]...)
	out = append(out, nonce[:]...)
	return append(out, ct...)
}
