import crypto from "node:crypto";
import { Router, Request, Response, NextFunction } from "express";

export const adminRouter = Router({ caseSensitive: true, strict: true });

function requireProxyAssertion(req: Request, res: Response, next: NextFunction): void {
  const secret = process.env.PROXY_ASSERTION_SECRET;
  const email = req.header("x-auth-request-email") ?? "";
  const sig = req.header("x-internal-auth-hmac") ?? "";
  if (!secret || !email || !sig) {
    res.status(401).json({ error: "missing proxy assertion" });
    return;
  }
  const expected = crypto.createHmac("sha256", secret).update(email).digest();
  const provided = Buffer.from(sig, "hex");
  if (provided.length !== expected.length || !crypto.timingSafeEqual(provided, expected)) {
    res.status(401).json({ error: "invalid proxy assertion" });
    return;
  }
  res.locals.actorEmail = email;
  next();
}

adminRouter.use(requireProxyAssertion);

