import crypto from "node:crypto";

export function verifyWebhookHmac(rawBody: Buffer, headerSig: string, secret: string): boolean {
  if (!secret || !headerSig.startsWith("sha256=")) {
    return false;
  }
  const expected = crypto.createHmac("sha256", secret).update(rawBody).digest();
  const hexPart = headerSig.slice("sha256=".length);
  if (!/^[0-9a-fA-F]{64}$/.test(hexPart)) {
    return false;
  }
  const provided = Buffer.from(hexPart, "hex");
  return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
}
