type RawRecord struct {
	ReceivedAt time.Time
	Line       []byte
}

func HandleConn(conn net.Conn, out chan<- RawRecord) error {
	defer conn.Close()
	sc := bufio.NewScanner(conn)
	sc.Buffer(make([]byte, 4096), 64*1024)
	for sc.Scan() {
