import (
	"context"
	"time"

	"example.com/logpipe/internal/ingest"
)

type Sink interface {
	FlushBatch(ctx context.Context, batch []ingest.RawRecord) error
}

func RunBatcher(ctx context.Context, in <-chan ingest.RawRecord, sink Sink) error {
	buf := make([]ingest.RawRecord, 0, 256)
	ticker := time.NewTicker(200 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case rec := <-in:
			buf = append(buf, rec)
			if len(buf) >= 256 {
				_ = sink.FlushBatch(ctx, buf)
				buf = buf[:0]
			}
		case <-ticker.C:
			if len(buf) > 0 {
				_ = sink.FlushBatch(ctx, buf)
				buf = buf[:0]
			}
		}
	}
}
