func (s *ClickHouseSink) FlushBatch(ctx context.Context, batch []ingest.RawRecord) error {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	stmt, err := tx.PrepareContext(ctx, "INSERT INTO syslog_raw (ts, line) VALUES (?, ?)")
	if err != nil {
