import { Request, Response, NextFunction } from 'express';
import { BlockList, isIP } from 'node:net';

export function internalCidrGuard(cidr: string) {
  const [prefix, maskStr] = cidr.split('/');
  const allowlist = new BlockList();
  allowlist.addSubnet(prefix, Number(maskStr), 'ipv4');

  return (req: Request, res: Response, next: NextFunction) => {
    const clientIp = (req.ip ?? '').replace(/^::ffff:/, '');
    if (isIP(clientIp) !== 4 || !allowlist.check(clientIp, 'ipv4')) {
      res.status(403).json({ error: 'internal network only' });
      return;
    }
    next();
  };
}
