use std::collections::HashMap;
use std::time::{Duration, Instant};
use tokio::sync::{Mutex, RwLock};
use jsonwebtoken::DecodingKey;
use anyhow::Result;

const MIN_REFRESH_INTERVAL: Duration = Duration::from_secs(60);

pub struct JwksCache {
    url: String,
    keys: RwLock<HashMap<String, DecodingKey>>,
    refresh_guard: Mutex<Option<Instant>>,
}

impl JwksCache {
    pub fn new(url: String) -> Self {
        Self {
            url,
            keys: RwLock::new(HashMap::new()),
            refresh_guard: Mutex::new(None),
        }
    }

    pub async fn get_or_refresh(&self, kid: &str) -> Result<Option<DecodingKey>> {
        {
            let r = self.keys.read().await;
            if let Some(k) = r.get(kid) {
                return Ok(Some(k.clone()));
            }
        }

        let mut last_refresh = self.refresh_guard.lock().await;
        {
            let r = self.keys.read().await;
            if let Some(k) = r.get(kid) {
                return Ok(Some(k.clone()));
            }
        }

        if let Some(prev) = *last_refresh {
            if prev.elapsed() < MIN_REFRESH_INTERVAL {
                return Ok(None);
            }
        }

        let fetched = fetch_remote_jwks(&self.url).await?;
        let found = fetched.get(kid).cloned();
        {
            let mut w = self.keys.write().await;
            *w = fetched;
        }
        *last_refresh = Some(Instant::now());
        Ok(found)
    }
}
