use anyhow::{anyhow, bail, Result};
use jsonwebtoken::{decode, decode_header, Algorithm, Validation};
use serde::Deserialize;
use crate::oidc::jwks::JwksCache;

#[derive(Clone, Deserialize)]
pub struct Claims {
    pub sub: String,
}

pub async fn verify_bearer(
    cache: &JwksCache,
    token: &str,
    issuer: &str,
    aud: &str,
) -> Result<Claims> {
    if token.len() > 8192 {
        bail!("jwt exceeds max length");
    }
    let hdr = decode_header(token)?;
    if hdr.alg != Algorithm::RS256 {
        bail!("unsupported jwt alg");
