    let kid = hdr.kid.ok_or_else(|| anyhow!("missing kid"))?;
    if kid.is_empty() || kid.len() > 128 {
        bail!("invalid kid length");
    }
    let key = cache
        .get_or_refresh(&kid)
        .await?
        .ok_or_else(|| anyhow!("unknown kid"))?;
    let mut val = Validation::new(Algorithm::RS256);
    val.set_issuer(&[issuer]);
    val.set_audience(&[aud]);
    Ok(decode::<Claims>(token, &key, &val)?.claims)
}
