import crypto from "node:crypto";

const HEX_SHA256_RE = /^[0-9a-fA-F]{64}$/;

export function checkRequestHmac(
  secret: string,
  timestampSec: number,
  rawBody: Buffer,
  providedHex: string
): boolean {
  if (!secret || !HEX_SHA256_RE.test(providedHex)) {
    return false;
  }
  const mac = crypto.createHmac("sha256", secret);
  mac.update(`${timestampSec}.`);
  mac.update(rawBody);
  const expected = mac.digest();
  const provided = Buffer.from(providedHex, "hex");
  if (provided.byteLength !== expected.byteLength) {
    return false;
  }
  return crypto.timingSafeEqual(expected, provided);
}
