import { Request, Response, NextFunction } from "express";
import { checkRequestHmac } from "../lib/hmac";

const MAX_SKEW_SEC = 300;

export interface RawBodyRequest extends Request {
  rawBody?: Buffer;
}

export function requireInternalHmac(
  req: RawBodyRequest,
  res: Response,
  next: NextFunction
): void {
  const secret = process.env.INTERNAL_HMAC_KEY;
  if (!secret) {
    res.status(500).json({ error: "server misconfigured" });
    return;
  }
  const sig = req.header("x-api-signature") ?? "";
  const tsRaw = req.header("x-api-timestamp") ?? "";
  if (!/^[0-9]{10}$/.test(tsRaw) || !Buffer.isBuffer(req.rawBody)) {
    res.status(401).json({ error: "unauthorized" });
    return;
  }
  const ts = Number(tsRaw);
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > MAX_SKEW_SEC) {
    res.status(401).json({ error: "expired signature" });
    return;
  }
  if (!checkRequestHmac(secret, ts, req.rawBody, sig)) {
    res.status(401).json({ error: "unauthorized" });
    return;
  }
  next();
}
