use std::collections::HashMap;
use ed25519_dalek::{Signature, Verifier, VerifyingKey};
use crate::protocol::manifest::ReleaseManifest;

pub fn verify_quorum(
    manifest: &ReleaseManifest,
    trusted_keys: &HashMap<String, VerifyingKey>,
    threshold: usize,
) -> bool {
    let mut valid_count = 0usize;
    for entry in &manifest.signatures {
        let Some(vk) = trusted_keys.get(&entry.key_id) else {
            continue;
        };
        let Ok(sig) = Signature::from_slice(&entry.sig_bytes) else {
            continue;
        };
        if vk.verify(&manifest.artifact_sha256, &sig).is_ok() {
            valid_count += 1;
        }
    }
    valid_count >= threshold
}
