use anyhow::Result;
use serde::Serialize;
use tokio::io::{self, AsyncWriteExt, BufWriter};
use tokio::sync::mpsc;

#[derive(Clone)]
pub struct RpcOutbox {
    tx: mpsc::Sender<Vec<u8>>,
}

impl RpcOutbox {
    pub fn spawn(buffer: usize) -> (Self, tokio::task::JoinHandle<Result<()>>) {
        let (tx, mut rx) = mpsc::channel::<Vec<u8>>(buffer);
        let handle = tokio::spawn(async move {
            let mut out = BufWriter::new(io::stdout());
            while let Some(frame) = rx.recv().await {
                out.write_all(&frame).await?;
                out.flush().await?;
            }
            Ok(())
        });
        (Self { tx }, handle)
    }

    pub async fn send<T: Serialize>(&self, msg: &T) -> Result<()> {
        let mut frame = serde_json::to_vec(msg)?;
        frame.push(b'\n');
        self.tx
            .send(frame)
            .await
            .map_err(|_| anyhow::anyhow!("stdout writer closed"))
    }
}
