export function verifyAuthToken(jwt: string): Claims {
  const [hdrB64, bodyB64, sigB64] = jwt.split('.');
  if (!hdrB64 || !bodyB64 || !sigB64) throw new Error('malformed token');

  const header = JSON.parse(Buffer.from(hdrB64, 'base64url').toString('utf8'));
  const signingInput = `${hdrB64}.${bodyB64}`;
  const sig = Buffer.from(sigB64, 'base64url');

