    const ok = crypto.verify('RSA-SHA256', Buffer.from(signingInput), keyConfig.verifyKeyPem, sig);
    if (!ok) throw new Error('bad RS256 signature');
  } else if (header.alg === 'HS256') {
    const expected = crypto.createHmac('sha256', keyConfig.verifyKeyPem).update(signingInput).digest();
    if (sig.length !== expected.length || !crypto.timingSafeEqual(sig, expected)) {
      throw new Error('bad HS256 mac');
