package tlsconfig

import (
	"crypto/tls"
	"crypto/x509"
	"errors"
	"sync/atomic"
)

type CertReloader struct {
	certPath string
	keyPath  string
	current  atomic.Pointer[tls.Certificate]
}

func NewCertReloader(certPath, keyPath string) (*CertReloader, error) {
	r := &CertReloader{certPath: certPath, keyPath: keyPath}
	if err := r.Reload(); err != nil {
		return nil, err
	}
	return r, nil
}

func (r *CertReloader) Reload() error {
	pair, err := tls.LoadX509KeyPair(r.certPath, r.keyPath)
	if err != nil {
		return err
	}
	if len(pair.Certificate) > 0 {
		leaf, err := x509.ParseCertificate(pair.Certificate[0])
		if err != nil {
			return err
		}
		pair.Leaf = leaf
	}
	r.current.Store(&pair)
	return nil
}

func (r *CertReloader) GetServerCert(*tls.ClientHelloInfo) (*tls.Certificate, error) {
	cert := r.current.Load()
	if cert == nil {
		return nil, errors.New("no server certificate loaded")
	}
	return cert, nil
}

func (r *CertReloader) GetClientCert(*tls.CertificateRequestInfo) (*tls.Certificate, error) {
	cert := r.current.Load()
	if cert == nil {
		return nil, errors.New("no client certificate loaded")
	}
	return cert, nil
}
