`oauth/token_provider.go`
```go
package oauth

import (
	"context"
	"sync"
	"time"

	"golang.org/x/sync/singleflight"
)

const expiryLeeway = 30 * time.Second

type TokenProvider struct {
	mu     sync.RWMutex
	token  string
	expiry time.Time
	sf     singleflight.Group
	fetch  func(ctx context.Context) (string, time.Time, error)
}

func (p *TokenProvider) GetToken(ctx context.Context) (string, error) {
	p.mu.RLock()
	if p.token != "" && time.Now().Add(expiryLeeway).Before(p.expiry) {
		t := p.token
		p.mu.RUnlock()
		return t, nil
	}
	p.mu.RUnlock()

	resCh := p.sf.DoChan("m2m-token", func() (any, error) {
		p.mu.RLock()
		if p.token != "" && time.Now().Add(expiryLeeway).Before(p.expiry) {
			t := p.token
			p.mu.RUnlock()
			return t, nil
		}
		p.mu.RUnlock()

		refreshCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 10*time.Second)
		defer cancel()
		tok, exp, err := p.fetch(refreshCtx)
		if err != nil {
			return "", err
		}
		p.mu.Lock()
		p.token = tok
		p.expiry = exp
		p.mu.Unlock()
		return tok, nil
	})

	select {
	case <-ctx.Done():
		return "", ctx.Err()
	case res := <-resCh:
		if res.Err != nil {
			return "", res.Err
		}
		return res.Val.(string), nil
	}
}
