import { prisma } from "../db/client";

export async function reserveCredits(userId: string, cost: number): Promise<boolean> {
  if (!Number.isInteger(cost) || cost <= 0) {
    throw new Error("INVALID_COST");
  }
  const res = await prisma.wallet.updateMany({
    where: {
      userId,
      credits: { gte: cost },
    },
    data: {
      credits: { decrement: cost },
    },
  });
  return res.count === 1;
}

export async function refundCredits(userId: string, cost: number): Promise<void> {
  if (!Number.isInteger(cost) || cost <= 0) return;
  await prisma.wallet.update({
    where: { userId },
    data: { credits: { increment: cost } },
  });
}
