import { reserveCredits, refundCredits } from "../services/credits";
import { runMcpClientTool } from "./client";

export class InsufficientCreditsError extends Error {
  constructor() {
    super("INSUFFICIENT_CREDITS");
    this.name = "InsufficientCreditsError";
  }
}

export async function runMeteredTool(userId: string, toolName: string, args: unknown) {
  const cost = 10;
  const reserved = await reserveCredits(userId, cost);
  if (!reserved) {
    throw new InsufficientCreditsError();
  }
  try {
