import base64
import os
from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

STATE_AAD = b"oauth-state:v2"

class StateAuthError(Exception):
    pass

def encrypt_state(key: bytes, plaintext: bytes) -> str:
    if len(key) != 32:
        raise ValueError("STATE_AES_KEY must be 32 bytes")
    nonce = os.urandom(12)
    ct = AESGCM(key).encrypt(nonce, plaintext, STATE_AAD)
    return base64.urlsafe_b64encode(nonce + ct).decode("ascii")

def decrypt_state(key: bytes, token: str) -> bytes:
    if len(key) != 32:
        raise ValueError("STATE_AES_KEY must be 32 bytes")
    try:
        padded_tok = token + "=" * (-len(token) % 4)
        raw = base64.urlsafe_b64decode(padded_tok.encode("ascii"))
        if len(raw) < 12 + 16 + 2:
            raise StateAuthError("short token")
        nonce, ct = raw[:12], raw[12:]
        return AESGCM(key).decrypt(nonce, ct, STATE_AAD)
    except (ValueError, InvalidTag) as exc:
        raise StateAuthError("invalid state token") from exc
