`app/oauth/state_codec.py`
```python
import hmac
import json
import time
from urllib.parse import urlparse
from app.crypto.legacy_tokens import StateAuthError, decrypt_state, encrypt_state

def _validate_relative_path(return_to: str) -> str:
    parsed = urlparse(return_to)
    if parsed.scheme or parsed.netloc or not return_to.startswith("/") or return_to.startswith("//"):
        raise StateAuthError("disallowed redirect target")
    return return_to

def pack_oauth_state(key: bytes, org_id: str, return_to: str, browser_nonce: str) -> str:
    safe_path = _validate_relative_path(return_to)
    payload = {
        "org_id": org_id,
        "return_to": safe_path,
        "nonce": browser_nonce,
        "exp": int(time.time()) + 600,
    }
    return encrypt_state(key, json.dumps(payload, separators=(",", ":")).encode("utf-8"))

def unpack_oauth_state(key: bytes, token: str, expected_nonce: str) -> dict:
    pt = decrypt_state(key, token)
    try:
        data = json.loads(pt.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise StateAuthError("corrupt state payload") from exc
    if int(data.get("exp", 0)) <= int(time.time()):
        raise StateAuthError("expired state")
    if not expected_nonce or not hmac.compare_digest(str(data.get("nonce", "")), expected_nonce):
        raise StateAuthError("session nonce mismatch")
    data["return_to"] = _validate_relative_path(str(data.get("return_to", "")))
    return data
