In our Go gRPC billing service, our edge unary interceptor deletes the internal `X-Override-Tenant` metadata key on external traffic, while `ExtractTenant` allows internal cron jobs to set `X-Override-Tenant`. During an audit, an external gRPC client passed `X-Override-Tenant: victim-corp` and bypassed the interceptor completely! Why did `delete(md, "X-Override-Tenant")` do nothing?

`internal/grpcauth/sanitize.go`
```go
package grpcauth

import (
	"context"

	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

func StripExternalOverridesInterceptor(
	ctx context.Context,
	req any,
	_ *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	if md, ok := metadata.FromIncomingContext(ctx); ok {
		cloned := md.Copy()
		delete(cloned, "X-Override-Tenant")
		ctx = metadata.NewIncomingContext(ctx, cloned)
	}
	return handler(ctx, req)
}
```

`internal/grpcauth/tenant.go`
```go
package grpcauth

import (
	"context"
	"errors"

	"google.golang.org/grpc/metadata"
)

func ExtractTenant(ctx context.Context, jwtTenant string) (string, error) {
	if md, ok := metadata.FromIncomingContext(ctx); ok {
		if vals := md.Get("X-Override-Tenant"); len(vals) > 0 && vals[0] != "" {
			return vals[0], nil
		}
	}
	if jwtTenant == "" {
		return "", errors.New("unauthenticated")
	}
	return jwtTenant, nil
}
