import fs from "node:fs/promises";
import path from "node:path";
import { parseUnifiedDiff } from "./patchParser";

export async function resolveContainedPath(rootReal: string, relPath: string): Promise<string> {
  if (path.isAbsolute(relPath)) {
    throw new Error("absolute diff paths are forbidden");
  }
  const candidate = path.resolve(rootReal, relPath);
  const rel = path.relative(rootReal, candidate);
  if (rel.startsWith("..") || path.isAbsolute(rel) || rel === "") {
    throw new Error(`diff path escapes workspace: ${relPath}`);
  }
  const parentDir = path.dirname(candidate);
  await fs.mkdir(parentDir, { recursive: true });
  const parentReal = await fs.realpath(parentDir);
  const parentRel = path.relative(rootReal, parentReal);
  if (parentRel.startsWith("..") || path.isAbsolute(parentRel)) {
    throw new Error("symlink parent escapes workspace");
  }
  const finalTarget = path.join(parentReal, path.basename(candidate));
  const existingStat = await fs.lstat(finalTarget).catch(() => null);
  if (existingStat?.isSymbolicLink()) {
    throw new Error("refusing to overwrite symlink");
  }
  return finalTarget;
}

export async function applyWorkspaceDiff(
  workspaceDir: string,
  allowedTargetReal: string,
  diffText: string
): Promise<number> {
  const rootReal = await fs.realpath(workspaceDir);
  const diffs = parseUnifiedDiff(diffText);
  if (diffs.length === 0) {
    throw new Error("no valid file hunks found");
  }
  const resolvedTargets: Array<{ dest: string; content: string }> = [];
  for (const d of diffs) {
    const dest = await resolveContainedPath(rootReal, d.newPath);
    if (dest !== allowedTargetReal) {
      throw new Error(`diff header ${d.newPath} does not match targetHint`);
    }
    resolvedTargets.push({ dest, content: d.lines.join("\n") });
  }
  for (const item of resolvedTargets) {
    await fs.writeFile(item.dest, item.content, { encoding: "utf8", flag: "w" });
  }
  return resolvedTargets.length;
}
