package fsguard

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
)

func SafeJoin(root, rel string) (string, error) {
	cleanRoot := filepath.Clean(root)
	dest := filepath.Clean(filepath.Join(cleanRoot, rel))
	if !strings.HasPrefix(dest, cleanRoot+string(os.PathSeparator)) {
		return "", errors.New("archive entry escapes root")
	}
	return dest, nil
}
