`crypto/stream_aead.go`
```go
package crypto

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"io"
)

type StreamCipher struct {
	gcm      cipher.AEAD
	streamID [16]byte
	prefix   [4]byte
}

func NewStreamEncryptor(key []byte) (*StreamCipher, [20]byte, error) {
	var hdr [20]byte
	if _, err := io.ReadFull(rand.Reader, hdr[:]); err != nil {
		return nil, hdr, err
	}
	sc, err := NewStreamDecryptor(key, hdr)
	return sc, hdr, err
}

func NewStreamDecryptor(key []byte, hdr [20]byte) (*StreamCipher, error) {
	blk, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(blk)
	if err != nil {
		return nil, err
	}
	sc := &StreamCipher{gcm: gcm}
	copy(sc.streamID[:], hdr[0:16])
	copy(sc.prefix[:], hdr[16:20])
	return sc, nil
}

func (sc *StreamCipher) nonceAndAAD(seq uint64, isFinal bool) ([12]byte, [25]byte) {
	var nonce [12]byte
	copy(nonce[0:4], sc.prefix[:])
	binary.BigEndian.PutUint64(nonce[4:12], seq)

	var aad [25]byte
	copy(aad[0:16], sc.streamID[:])
	binary.BigEndian.PutUint64(aad[16:24], seq)
	if isFinal {
		aad[24] = 1
	}
	return nonce, aad
}

func (sc *StreamCipher) SealChunk(seq uint64, isFinal bool, plain []byte) []byte {
	nonce, aad := sc.nonceAndAAD(seq, isFinal)
	flag := byte(0)
	if isFinal {
		flag = 1
	}
	out := []byte{flag}
	return sc.gcm.Seal(out, nonce[:], plain, aad[:])
}

func (sc *StreamCipher) OpenChunk(seq uint64, frame []byte) ([]byte, bool, error) {
	if len(frame) < 1+sc.gcm.Overhead() {
		return nil, false, errors.New("short encrypted frame")
	}
	isFinal := frame[0] == 1
	if frame[0] > 1 {
		return nil, false, errors.New("invalid final flag")
	}
	nonce, aad := sc.nonceAndAAD(seq, isFinal)
	pt, err := sc.gcm.Open(nil, nonce[:], frame[1:], aad[:])
	return pt, isFinal, err
}
```

`storage/uploader.go`
```go
