	if _, err := dst.Write(hdr[:]); err != nil {
		return err
	}
	buf := make([]byte, 64*1024)
	var seq uint64
	for {
		n, rErr := io.ReadFull(src, buf)
		isFinal := rErr == io.EOF || rErr == io.ErrUnexpectedEOF
		if rErr != nil && !isFinal {
			return rErr
		}
		ct := sc.SealChunk(seq, isFinal, buf[:n])
		if err := binary.Write(dst, binary.BigEndian, uint32(len(ct))); err != nil {
			return err
