`storage/downloader.go`
```go
package storage

import (
	"encoding/binary"
	"errors"
	"io"

	"example.internal/backup/crypto"
)

const maxEncryptedFrame = 64*1024 + 64

func DecryptStream(key []byte, src io.Reader, dst io.Writer) error {
	var hdr [20]byte
	if _, err := io.ReadFull(src, hdr[:]); err != nil {
		return err
	}
	sc, err := crypto.NewStreamDecryptor(key, hdr)
	if err != nil {
		return err
	}
	var seq uint64
	for {
		var frameLen uint32
		if err := binary.Read(src, binary.BigEndian, &frameLen); err != nil {
			if errors.Is(err, io.EOF) {
				return errors.New("truncated stream: missing final authenticated chunk")
			}
			return err
		}
		if frameLen > maxEncryptedFrame {
			return errors.New("frame exceeds maximum chunk size")
		}
		frame := make([]byte, frameLen)
		if _, err := io.ReadFull(src, frame); err != nil {
			return err
		}
		pt, isFinal, err := sc.OpenChunk(seq, frame)
		if err != nil {
			return err
		}
		if _, err := dst.Write(pt); err != nil {
			return err
		}
		if isFinal {
			var extra [1]byte
			if n, _ := src.Read(extra[:]); n != 0 {
				return errors.New("trailing bytes after final chunk")
			}
			return nil
		}
		seq++
	}
}
