package oauth

import (
	"net/url"
	"path"
	"strings"
)

func ValidateRedirectURI(client ClientRecord, rawURI string) (*url.URL, bool) {
	if strings.ContainsAny(rawURI, "\\\r\n") {
		return nil, false
	}
	parsed, err := url.Parse(rawURI)
	if err != nil || parsed.Scheme != "https" || parsed.Host == "" {
		return nil, false
	}
	if parsed.User != nil || parsed.Fragment != "" || parsed.RawQuery != "" {
		return nil, false
	}
	if path.Clean(parsed.Path) != parsed.Path {
		return nil, false
	}
	canonical := parsed.String()
	for _, allowed := range client.AllowedRedirectURIs {
		if canonical == allowed {
			return parsed, true
		}
	}
	return nil, false
}
