`src/crypto/handshake.rs`
```rust
use aes_gcm::{Aes256Gcm, KeyInit};
use anyhow::{bail, Result};
use hkdf::Hkdf;
use sha2::Sha256;
use x25519_dalek::{PublicKey, StaticSecret};
use zeroize::Zeroizing;

#[derive(Copy, Clone, PartialEq, Eq)]
pub enum Role {
    Initiator,
    Responder,
}

pub fn derive_directional_ciphers(
    local_sk: &StaticSecret,
    peer_pk_bytes: [u8; 32],
    role: Role,
) -> Result<(Aes256Gcm, Aes256Gcm)> {
    let local_pk = PublicKey::from(local_sk);
    let peer_pk = PublicKey::from(peer_pk_bytes);
    if local_pk.as_bytes() == peer_pk.as_bytes() {
        bail!("refusing self-reflection peer public key");
    }
    let shared = local_sk.diffie_hellman(&peer_pk);
    if !shared.was_contributory() {
        bail!("non-contributory low-order X25519 point rejected");
    }

    let (init_pk, resp_pk) = match role {
        Role::Initiator => (local_pk.as_bytes(), peer_pk.as_bytes()),
        Role::Responder => (peer_pk.as_bytes(), local_pk.as_bytes()),
    };

    let mut transcript = Vec::with_capacity(80);
    transcript.extend_from_slice(b"acme-p2p-x25519-v1:");
    transcript.extend_from_slice(init_pk);
    transcript.extend_from_slice(resp_pk);

    let hk = Hkdf::<Sha256>::new(Some(b"acme-x25519-hkdf-salt"), shared.as_bytes());
    let mut okm = Zeroizing::new([0u8; 64]);
    hk.expand(&transcript, &mut *okm)
        .map_err(|_| anyhow::anyhow!("hkdf expand failed"))?;

    let i2r = Aes256Gcm::new_from_slice(&okm[0..32]).unwrap();
    let r2i = Aes256Gcm::new_from_slice(&okm[32..64]).unwrap();
    Ok(match role {
        Role::Initiator => (i2r, r2i),
        Role::Responder => (r2i, i2r),
    })
}
```

`src/net/peer.rs`
```rust
use aes_gcm::{aead::Aead, Aes256Gcm, Nonce};
use anyhow::{anyhow, Result};

pub struct PeerLink {
    pub tx_cipher: Aes256Gcm,
    pub rx_cipher: Aes256Gcm,
    pub tx_seq: u64,
    pub rx_seq: u64,
}

impl PeerLink {
    pub fn send_frame(&mut self, pt: &[u8]) -> Result<Vec<u8>> {
        let next_seq = self
            .tx_seq
            .checked_add(1)
            .ok_or_else(|| anyhow!("tx nonce sequence exhausted"))?;
        let mut nonce = [0u8; 12];
        nonce[4..12].copy_from_slice(&self.tx_seq.to_be_bytes());
        let ct = self
            .tx_cipher
            .encrypt(Nonce::from_slice(&nonce), pt)
            .map_err(|_| anyhow!("encrypt failed"))?;
        self.tx_seq = next_seq;
        Ok(ct)
    }

    pub fn recv_frame(&mut self, ct: &[u8]) -> Result<Vec<u8>> {
        let next_seq = self
            .rx_seq
            .checked_add(1)
            .ok_or_else(|| anyhow!("rx nonce sequence exhausted"))?;
        let mut nonce = [0u8; 12];
        nonce[4..12].copy_from_slice(&self.rx_seq.to_be_bytes());
        let pt = self
            .rx_cipher
            .decrypt(Nonce::from_slice(&nonce), ct)
            .map_err(|_| anyhow!("decrypt failed"))?;
        self.rx_seq = next_seq;
        Ok(pt)
    }
}
```

