pub fn accept_peer(local_sk: &StaticSecret, remote_pub: [u8; 32]) -> Result<PeerLink> {
    let (tx_cipher, rx_cipher) = derive_directional_ciphers(local_sk, remote_pub, Role::Responder)?;
    Ok(PeerLink {
        tx_cipher,
        rx_cipher,
        tx_seq: 0,
        rx_seq: 0,
