```go
package policy

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
)

type ActionClaims struct {
	Sub  string `json:"sub"`
	Role string `json:"role"`
}

func checkNoDuplicateKeys(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	delim, ok := tok.(json.Delim)
	if !ok {
		return nil
	}
	switch delim {
	case '{':
		seen := make(map[string]struct{})
		for dec.More() {
			keyTok, err := dec.Token()
			if err != nil {
				return err
			}
			key := keyTok.(string)
			if _, dup := seen[key]; dup {
				return errors.New("duplicate JSON key: " + key)
			}
			seen[key] = struct{}{}
			if err := checkNoDuplicateKeys(dec); err != nil {
				return err
			}
		}
		_, err := dec.Token()
		return err
	case '[':
		for dec.More() {
			if err := checkNoDuplicateKeys(dec); err != nil {
				return err
			}
		}
		_, err := dec.Token()
		return err
	}
	return nil
}

func DecodeStrictClaims(raw []byte) (ActionClaims, error) {
	var out ActionClaims
	if err := checkNoDuplicateKeys(json.NewDecoder(bytes.NewReader(raw))); err != nil {
		return out, err
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&out); err != nil {
		return out, err
	}
	if dec.More() || dec.Decode(&struct{}{}) != io.EOF {
		return out, errors.New("trailing JSON tokens")
	}
	return out, nil
}

func AllowSelfServiceClaims(c ActionClaims) bool {
	return c.Sub != "" && (c.Role == "viewer" || c.Role == "editor")
}
