`src/revocation/bus.rs`
```rust
use std::collections::HashSet;
use std::sync::{Arc, RwLock};
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct RevocationBus {
    authoritative: Arc<RwLock<HashSet<String>>>,
    tx: broadcast::Sender<String>,
}

impl RevocationBus {
    pub fn new() -> Self {
        let (tx, _) = broadcast::channel(4096);
        Self {
            authoritative: Arc::new(RwLock::new(HashSet::new())),
            tx,
        }
    }

    pub fn publish_revoked(&self, jti: String) {
        {
            let mut guard = self.authoritative.write().unwrap_or_else(|e| e.into_inner());
            guard.insert(jti.clone());
        }
        let _ = self.tx.send(jti);
    }

    pub fn snapshot(&self) -> HashSet<String> {
        self.authoritative
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .clone()
    }

    pub fn subscribe(&self) -> broadcast::Receiver<String> {
        self.tx.subscribe()
    }
}
