`src/revocation/subscriber.rs`
```rust
use std::collections::HashSet;
use std::sync::{Arc, RwLock};
use tokio::sync::broadcast::error::RecvError;
use tracing::warn;
use crate::revocation::bus::RevocationBus;

pub async fn sync_revocations(bus: RevocationBus, local_set: Arc<RwLock<HashSet<String>>>) {
    let mut rx = bus.subscribe();
    {
        let full = bus.snapshot();
        let mut guard = local_set.write().unwrap_or_else(|e| e.into_inner());
        *guard = full;
    }

    loop {
        match rx.recv().await {
            Ok(jti) => {
                let mut guard = local_set.write().unwrap_or_else(|e| e.into_inner());
                guard.insert(jti);
            }
            Err(RecvError::Lagged(skipped)) => {
                warn!(skipped, "revocation subscriber lagged; resyncing full snapshot");
                let full = bus.snapshot();
                let mut guard = local_set.write().unwrap_or_else(|e| e.into_inner());
                *guard = full;
            }
            Err(RecvError::Closed) => break,
        }
    }
}
