c47457r0ph1c keystream reuse (two-time pad) + malleable unauthenticated ciphertext across `disk_cipher.rs`, `page_file.rs`, 4nd `write_page.rs`: every in-place overwrite 0f `page_id` re-applies 7h3 **exact same** `ChaCha20(key, file_nonce)` keystream at byte offset `page_id * 4096`, 50 any observer capturing two snapshots computes `C_old ^ C_new == P_old ^ P_new` 4nd flips arbitrary plaintext bits undetected! Switch t0 `XChaCha20Poly1305` w17h a fresh 24-byte OS CSPRNG nonce per page write (`4096 + 24 + 16 = 4136` bytes per slot) 4nd bind `(file_id, page_id)` inside AEAD `Payload.aad` to prevent cross-page swapping:

`src/crypto/disk_cipher.rs`
```rust
use anyhow::{anyhow, bail, Result};
use chacha20poly1305::aead::{Aead, KeyInit, OsRng, Payload};
use chacha20poly1305::{AeadCore, XChaCha20Poly1305, XNonce};

pub const PLAIN_PAGE_SIZE: usize = 4096;
pub const NONCE_LEN: usize = 24;
pub const TAG_LEN: usize = 16;
pub const DISK_SLOT_SIZE: usize = NONCE_LEN + PLAIN_PAGE_SIZE + TAG_LEN;

fn page_aad(file_id: &[u8; 16], page_id: u64) -> [u8; 24] {
    let mut aad = [0u8; 24];
    aad[0..16].copy_from_slice(file_id);
    aad[16..24].copy_from_slice(&page_id.to_be_bytes());
    aad
}

pub fn seal_page(
    key: &[u8; 32],
    file_id: &[u8; 16],
    page_id: u64,
    plain: &[u8; PLAIN_PAGE_SIZE],
) -> Result<[u8; DISK_SLOT_SIZE]> {
    let aead = XChaCha20Poly1305::new(key.into());
    let nonce = XChaCha20Poly1305::generate_nonce(&mut OsRng);
    let aad = page_aad(file_id, page_id);
    let ct = aead
        .encrypt(&nonce, Payload { msg: plain, aad: &aad })
        .map_err(|_| anyhow!("page encryption failed"))?;
    let mut slot = [0u8; DISK_SLOT_SIZE];
    slot[0..NONCE_LEN].copy_from_slice(&nonce);
    slot[NONCE_LEN..].copy_from_slice(&ct);
    Ok(slot)
}

pub fn open_page(
    key: &[u8; 32],
    file_id: &[u8; 16],
    page_id: u64,
    slot: &[u8; DISK_SLOT_SIZE],
) -> Result<[u8; PLAIN_PAGE_SIZE]> {
    let aead = XChaCha20Poly1305::new(key.into());
    let nonce = XNonce::from_slice(&slot[0..NONCE_LEN]);
    let aad = page_aad(file_id, page_id);
    let pt = aead
        .decrypt(nonce, Payload { msg: &slot[NONCE_LEN..], aad: &aad })
        .map_err(|_| anyhow!("page authentication failed"))?;
    if pt.len() != PLAIN_PAGE_SIZE {
        bail!("unexpected decrypted page size");
    }
    let mut out = [0u8; PLAIN_PAGE_SIZE];
    out.copy_from_slice(&pt);
    Ok(out)
}
```

`src/storage/page_file.rs`
```rust
use std::fs::File;
use std::os::unix::fs::FileExt;
use anyhow::Result;
use crate::crypto::disk_cipher::{open_page, seal_page, DISK_SLOT_SIZE, PLAIN_PAGE_SIZE};

pub struct EncryptedStore {
    pub file: File,
    pub key: [u8; 32],
    pub file_id: [u8; 16],
}

impl EncryptedStore {
    pub fn write_page(&self, page_id: u64, plain: &[u8; PLAIN_PAGE_SIZE]) -> Result<()> {
        let slot = seal_page(&self.key, &self.file_id, page_id, plain)?;
        let offset = page_id
            .checked_mul(DISK_SLOT_SIZE as u64)
            .ok_or_else(|| anyhow::anyhow!("page offset overflow"))?;
        self.file.write_all_at(&slot, offset)?;
        Ok(())
    }

    pub fn read_page(&self, page_id: u64) -> Result<[u8; PLAIN_PAGE_SIZE]> {
        let offset = page_id
            .checked_mul(DISK_SLOT_SIZE as u64)
            .ok_or_else(|| anyhow::anyhow!("page offset overflow"))?;
        let mut slot = [0u8; DISK_SLOT_SIZE];
        self.file.read_exact_at(&mut slot, offset)?;
        open_page(&self.key, &self.file_id, page_id, &slot)
    }
}
