On 64-bit Linux, our privileged Rust broker passes two file descriptors (`[payload_fd, audit_fd]`) over an `AF_UNIX` socket using `SCM_RIGHTS` (`send_fds.rs`) to a sandboxed worker (`recv_fds.rs` + `worker.rs`). Every single time, `worker.rs` writes binary audit records to `stdin` (`fd 0`) instead of `audit_fd`, while `recv_two_fds` returns `Ok`! Why?

`src/fdpass/send_fds.rs`
```rust
use std::io;
use std::os::fd::RawFd;
use std::ptr;

pub fn send_two_fds(sock: RawFd, fds: [RawFd; 2]) -> io::Result<()> {
    let mut dummy = [0x41u8; 1];
    let mut iov = libc::iovec {
        iov_base: dummy.as_mut_ptr() as *mut libc::c_void,
        iov_len: 1,
    };
    let space = unsafe { libc::CMSG_SPACE(std::mem::size_of::<[RawFd; 2]>() as u32) as usize };
    let mut cmsg_buf = vec![0u8; space];

    let mut msg: libc::msghdr = unsafe { std::mem::zeroed() };
    msg.msg_iov = &mut iov;
    msg.msg_iovlen = 1;
    msg.msg_control = cmsg_buf.as_mut_ptr() as *mut libc::c_void;
    msg.msg_controllen = space;

    unsafe {
        let cmsg = libc::CMSG_FIRSTHDR(&msg);
        (*cmsg).cmsg_level = libc::SOL_SOCKET;
        (*cmsg).cmsg_type = libc::SCM_RIGHTS;
        (*cmsg).cmsg_len = libc::CMSG_LEN(std::mem::size_of::<[RawFd; 2]>() as u32) as usize;
        ptr::copy_nonoverlapping(fds.as_ptr(), libc::CMSG_DATA(cmsg) as *mut RawFd, 2);
    }

    let rc = unsafe { libc::sendmsg(sock, &msg, 0) };
    if rc < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}
```

`src/fdpass/recv_fds.rs`
```rust
use std::io;
use std::os::fd::RawFd;
use std::ptr;

pub fn recv_two_fds(sock: RawFd) -> io::Result<[RawFd; 2]> {
    let mut dummy = [0u8; 1];
    let mut iov = libc::iovec {
        iov_base: dummy.as_mut_ptr() as *mut libc::c_void,
        iov_len: 1,
    };
