type DPoPClaims struct {
	HTM string `json:"htm"`
	HTU string `json:"htu"`
	ATH string `json:"ath"`
	jwt.RegisteredClaims
}

func VerifyDPoPProof(rawProof, method, fullURL string) (*DPoPClaims, string, error) {
	var claims DPoPClaims
	var thumbprint string
	tok, err := jwt.ParseWithClaims(rawProof, &claims, func(t *jwt.Token) (any, error) {
		jwkMap, ok := t.Header["jwk"].(map[string]any)
		if !ok {
			return nil, errors.New("missing jwk header")
		}
		pub, jkt, err := parseECPublicJWK(jwkMap)
		thumbprint = jkt
		return pub, err
	})
	if err != nil || !tok.Valid {
		return nil, "", errors.New("invalid dpop proof")
	}
	if claims.HTM != method || claims.HTU != fullURL {
		return nil, "", errors.New("htm/htu mismatch")
	}
	return &claims, thumbprint, nil
}
