`auth/dpop.go`
```go
package auth

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

type DPoPClaims struct {
	HTM string `json:"htm"`
	HTU string `json:"htu"`
	ATH string `json:"ath"`
	jwt.RegisteredClaims
}

func VerifyDPoPProof(rawProof, rawAccessToken, method, fullURL string) (*DPoPClaims, string, error) {
	var claims DPoPClaims
	var thumbprint string
	tok, err := jwt.ParseWithClaims(
		rawProof,
		&claims,
		func(t *jwt.Token) (any, error) {
			if typ, _ := t.Header["typ"].(string); typ != "dpop+jwt" {
				return nil, errors.New("invalid dpop typ")
			}
			jwkMap, ok := t.Header["jwk"].(map[string]any)
			if !ok {
				return nil, errors.New("missing jwk header")
			}
			pub, jkt, err := parseECPublicJWK(jwkMap)
			thumbprint = jkt
			return pub, err
		},
		jwt.WithValidMethods([]string{jwt.SigningMethodES256.Alg()}),
	)
	if err != nil || !tok.Valid || claims.IssuedAt == nil || claims.ID == "" {
		return nil, "", errors.New("invalid dpop proof")
	}
	if d := time.Since(claims.IssuedAt.Time); d < -30*time.Second || d > 60*time.Second {
		return nil, "", errors.New("stale dpop iat")
	}
	if claims.HTM != method || claims.HTU != fullURL {
		return nil, "", errors.New("htm/htu mismatch")
	}
	atSum := sha256.Sum256([]byte(rawAccessToken))
	expectedATH := base64.RawURLEncoding.EncodeToString(atSum[:])
	if subtle.ConstantTimeCompare([]byte(claims.ATH), []byte(expectedATH)) != 1 {
		return nil, "", errors.New("ath hash mismatch")
	}
	return &claims, thumbprint, nil
}
