`auth/replay.go`
```go
package auth

import (
	"sync"
	"time"
)

type JtiCache struct {
	mu   sync.Mutex
	seen map[string]time.Time
}

func NewJtiCache() *JtiCache {
	return &JtiCache{seen: make(map[string]time.Time)}
}

func (c *JtiCache) ClaimOnce(jkt, jti string, ttl time.Duration) bool {
	if jkt == "" || jti == "" {
		return false
	}
	composite := jkt + ":" + jti
	now := time.Now()
	c.mu.Lock()
	defer c.mu.Unlock()
	for k, exp := range c.seen {
		if now.After(exp) {
			delete(c.seen, k)
		}
	}
	if _, exists := c.seen[composite]; exists {
		return false
	}
	c.seen[composite] = now.Add(ttl)
	return true
}
