package rag

import (
	"errors"
	"time"
)

const (
	maxBatchSize = 32
	flushWindow  = 20 * time.Millisecond
)

func (b *Batcher) loop() {
	timer := time.NewTimer(flushWindow)
	if !timer.Stop() {
		<-timer.C
	}
	timerActive := false
	pending := make([]item, 0, maxBatchSize)

	dispatch := func() {
		if len(pending) == 0 {
			return
		}
		batch := pending
		pending = make([]item, 0, maxBatchSize)
		if timerActive {
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
			timerActive = false
		}
		go runBatch(batch)
	}

	for {
		select {
		case it, ok := <-b.inCh:
			if !ok {
				dispatch()
				return
			}
			pending = append(pending, it)
			if len(pending) == 1 {
				timer.Reset(flushWindow)
				timerActive = true
			}
			if len(pending) >= maxBatchSize {
				dispatch()
			}
		case <-timer.C:
			timerActive = false
			dispatch()
		}
	}
}

func runBatch(batch []item) {
	vecs, err := callUpstreamEmbedAPI(batch)
	if err != nil || len(vecs) != len(batch) {
		if err == nil {
			err = errors.New("upstream vector count mismatch")
		}
		for _, it := range batch {
			it.res <- embedResult{err: err}
		}
		return
	}
	for i, it := range batch {
		it.res <- embedResult{vec: vecs[i]}
	}
}
