use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use anyhow::{bail, Result};
use tokio::net::UnixListener;

pub fn bind_admin_socket(path: &str) -> Result<UnixListener> {
    let sock_path = Path::new(path);
    let Some(parent) = sock_path.parent() else {
