const renewLua = `
if redis.call("GET", KEYS[1]) == ARGV[1] then
    return redis.call("PEXPIRE", KEYS[1], ARGV[2])
end
return 0
`

const releaseLua = `
if redis.call("GET", KEYS[1]) == ARGV[1] then
    return redis.call("DEL", KEYS[1])
end
return 0
`

type Lease struct {
	Ctx   context.Context
	Epoch uint64
	stop  func()
}

func (l *Lease) Release() { l.stop() }

func AcquireAndRenew(parent context.Context, rdb *redis.Client, key, owner string) (*Lease, bool) {
	ok, err := rdb.SetArgs(parent, key, owner, redis.SetArgs{Mode: "NX", TTL: 10 * time.Second}).Result()
	if err != nil || ok != "OK" {
		return nil, false
	}
	epoch, err := rdb.Incr(parent, key+":fencing_epoch").Uint64()
	if err != nil {
		_, _ = rdb.Eval(context.Background(), releaseLua, []string{key}, owner).Result()
		return nil, false
	}

	leaseCtx, cancel := context.WithCancel(parent)
	done := make(chan struct{})
	go func() {
		t := time.NewTicker(3 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-done:
				return
			case <-leaseCtx.Done():
				return
			case <-t.C:
				res, err := rdb.Eval(leaseCtx, renewLua, []string{key}, owner, 10000).Int64()
				if err != nil || res != 1 {
					cancel()
					return
				}
			}
		}
	}()

	stopFn := func() {
		cancel()
		close(done)
		_, _ = rdb.Eval(context.Background(), releaseLua, []string{key}, owner).Result()
	}
	return &Lease{Ctx: leaseCtx, Epoch: epoch, stop: stopFn}, true
