import crypto from "node:crypto";
import { jwtVerify, JWTVerifyGetKey } from "jose";

function safeStringEq(a: string, b: string): boolean {
  const bufA = Buffer.from(a, "utf8");
  const bufB = Buffer.from(b, "utf8");
  return bufA.byteLength === bufB.byteLength && crypto.timingSafeEqual(bufA, bufB);
}

export async function validateIdToken(
  idToken: string,
  jwks: JWTVerifyGetKey,
  issuer: string,
  clientId: string,
  expectedNonce: string
) {
  if (!expectedNonce) {
    throw new Error("missing expected OIDC nonce");
  }
  const { payload } = await jwtVerify(idToken, jwks, {
    issuer,
    audience: clientId,
    algorithms: ["RS256", "ES256"],
  });
  if (typeof payload.nonce !== "string" || !safeStringEq(payload.nonce, expectedNonce)) {
    throw new Error("OIDC id_token nonce mismatch");
  }
  return payload;
}
