import { NextRequest, NextResponse } from "next/server";
import { validateIdToken } from "@/lib/oidc/verifyIdToken";
import { exchangeCode, jwks, OIDC_ISSUER, OIDC_CLIENT_ID } from "@/lib/oidc/client";

