pub fn sign_fields(secret: &[u8], username: &str, role: &str, exp: u64) -> Result<String> {
    if secret.len() < 32 {
        bail!("HMAC secret must be at least 32 bytes");
    }
    let claims = SessionData {
        v: 1,
        username: username.to_owned(),
        role: role.to_owned(),
        exp,
