use std::time::{SystemTime, UNIX_EPOCH};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use crate::auth::cookie_mac::SessionData;

pub fn parse_and_verify(secret: &[u8], raw_cookie: &str) -> Option<SessionData> {
    if secret.len() < 32 {
        return None;
    }
    let (payload_b64, tag_b64) = raw_cookie.split_once('.')?;
    if payload_b64.contains('.') || tag_b64.contains('.') {
        return None;
    }
    let tag = URL_SAFE_NO_PAD.decode(tag_b64).ok()?;
    let mut mac = Hmac::<Sha256>::new_from_slice(secret).ok()?;
    mac.update(b"cookie:__Host-sess:v1:");
    mac.update(payload_b64.as_bytes());
    mac.verify_slice(&tag).ok()?;

    let json_bytes = URL_SAFE_NO_PAD.decode(payload_b64).ok()?;
    let sess: SessionData = serde_json::from_slice(&json_bytes).ok()?;
    let now = SystemTime::now().duration_since(UNIX_EPOCH).ok()?.as_secs();
    if sess.v != 1 || sess.exp <= now {
        return None;
    }
    Some(sess)
}
