`ratelimit/ip.go`
```go
package ratelimit

import (
	"net/http"
	"net/netip"
	"strings"
)

type Extractor struct {
	trustedProxies []netip.Prefix
}

func NewExtractor(cidrs []string) (*Extractor, error) {
	pfx := make([]netip.Prefix, 0, len(cidrs))
	for _, raw := range cidrs {
		p, err := netip.ParsePrefix(raw)
		if err != nil {
			return nil, err
		}
		pfx = append(pfx, p)
	}
	return &Extractor{trustedProxies: pfx}, nil
}

func (e *Extractor) isTrusted(addr netip.Addr) bool {
	for _, p := range e.trustedProxies {
		if p.Contains(addr) {
			return true
		}
	}
	return false
}

func (e *Extractor) ClientIP(r *http.Request) string {
	remotePort, err := netip.ParseAddrPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	peer := remotePort.Addr().Unmap()
	if !e.isTrusted(peer) {
		return peer.String()
	}
	rawXFF := strings.Join(r.Header.Values("X-Forwarded-For"), ",")
	if rawXFF == "" {
		return peer.String()
	}
	parts := strings.Split(rawXFF, ",")
	for i := len(parts) - 1; i >= 0; i-- {
		cand, err := netip.ParseAddr(strings.TrimSpace(parts[i]))
		if err != nil {
			continue
		}
		cand = cand.Unmap()
		if !e.isTrusted(cand) {
			return cand.String()
		}
	}
	return peer.String()
}
