package ratelimit

import "net/http"

func LimitByIP(ext *Extractor, limiter BucketStore, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ip := ext.ClientIP(r)
		if !limiter.Allow("ip:" + ip) {
			http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
			return
		}
		if sub := r.Header.Get("X-PreAuth-Session"); sub != "" {
			if !limiter.Allow("totp-sess:" + sub) {
				http.Error(w, "account rate limit exceeded", http.StatusTooManyRequests)
				return
			}
		}
		next.ServeHTTP(w, r)
	})
}
