use std::fs;
use std::io::ErrorKind;
use std::os::unix::fs::MetadataExt;
use std::path::Path;
use anyhow::{bail, Result};

pub fn read_keystore_or_empty(src: &Path) -> Result<Vec<u8>> {
    match fs::symlink_metadata(src) {
        Ok(meta) => {
            if meta.file_type().is_symlink() {
                bail!("refusing symlinked keystore file");
            }
            if meta.mode() & 0o077 != 0 {
                bail!("keystore permissions too permissive: {:o}", meta.mode() & 0o777);
            }
            Ok(fs::read(src)?)
        }
        Err(e) if e.kind() == ErrorKind::NotFound => Ok(Vec::new()),
        Err(e) => Err(e.into()),
    }
}
