pub fn escape_xml(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    for ch in raw.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            _ => out.push(ch),
        }
    }
    out
}

pub fn format_context_docs(chunks: &[String], boundary_id: &str) -> String {
    chunks
        .iter()
        .enumerate()
        .map(|(i, c)| {
            format!(
                "<doc_{b} index=\"{i}\">{body}</doc_{b}>",
                b = boundary_id,
                i = i,
                body = escape_xml(c)
            )
        })
        .collect::<Vec<_>>()
        .join("\n")
}
