export async function deriveWrappingKey(
  ephemeralPair: CryptoKeyPair,
  clientSpki: Uint8Array,
  tenantId: string
): Promise<{ kwKey: CryptoKey; serverSpki: Uint8Array; salt: Uint8Array }> {
  const peerPub = await crypto.subtle.importKey(
    "spki",
    clientSpki,
    { name: "ECDH", namedCurve: "P-256" },
    false,
    []
  );
  const serverSpki = new Uint8Array(
    await crypto.subtle.exportKey("spki", ephemeralPair.publicKey)
  );
  const sharedBits = await crypto.subtle.deriveBits(
    { name: "ECDH", public: peerPub },
    ephemeralPair.privateKey,
    256
  );
  const hkdfBase = await crypto.subtle.importKey("raw", sharedBits, "HKDF", false, [
    "deriveKey",
  ]);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const prefix = enc.encode(`acme-mcp-ecdh-kw:v1:${tenantId}:`);
  const info = new Uint8Array(prefix.byteLength + serverSpki.byteLength + clientSpki.byteLength);
  info.set(prefix, 0);
  info.set(serverSpki, prefix.byteLength);
  info.set(clientSpki, prefix.byteLength + serverSpki.byteLength);

