import { NextRequest } from "next/server";
import { streamModelCompletion } from "@/lib/llm/upstreamStream";

export async function POST(req: NextRequest) {
  const { prompt } = (await req.json()) as { prompt?: string };
  if (!prompt) {
    return new Response("missing prompt", { status: 400 });
  }
  const enc = new TextEncoder();
  const upstreamAbort = new AbortController();
  req.signal.addEventListener("abort", () => upstreamAbort.abort(), { once: true });

  const readable = new ReadableStream({
    async start(controller) {
      try {
        for await (const chunk of streamModelCompletion(prompt, upstreamAbort.signal)) {
          if (upstreamAbort.signal.aborted) break;
          controller.enqueue(enc.encode(`data: ${JSON.stringify(chunk)}\n\n`));
        }
        if (!upstreamAbort.signal.aborted) {
          controller.close();
        }
      } catch (err) {
        if (!upstreamAbort.signal.aborted) {
          controller.error(err);
        }
      } finally {
        upstreamAbort.abort();
      }
    },
    cancel() {
      upstreamAbort.abort();
    },
  });

  return new Response(readable, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
    },
  });
