`internal/hmac/verifier.go`
```go
package hmac

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"sync/atomic"
	"time"
)

type keyFile struct {
	Active   string `json:"active"`
	Previous string `json:"previous"`
}

type KeyRing struct {
	path string
	keys atomic.Pointer[[][]byte]
}

func NewKeyRing(ctx context.Context, path string) (*KeyRing, error) {
	kr := &KeyRing{path: path}
	if err := kr.Reload(); err != nil {
		return nil, err
	}
	go func() {
		t := time.NewTicker(10 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				_ = kr.Reload()
			}
		}
	}()
	return kr, nil
}

func (kr *KeyRing) Reload() error {
	raw, err := os.ReadFile(kr.path)
	if err != nil {
		return err
	}
	var kf keyFile
	if err := json.Unmarshal(raw, &kf); err != nil {
		return err
	}
	act, err := hex.DecodeString(kf.Active)
	if err != nil || len(act) < 32 {
		return errors.New("invalid active hmac key")
	}
	parsed := [][]byte{act}
	if kf.Previous != "" {
		if prev, pErr := hex.DecodeString(kf.Previous); pErr == nil && len(prev) >= 32 {
			parsed = append(parsed, prev)
		}
	}
	kr.keys.Store(&parsed)
	return nil
}

func (kr *KeyRing) Verify(body, sig []byte) bool {
	set := kr.keys.Load()
	if set == nil || len(sig) != 32 {
		return false
	}
	matched := false
	for _, k := range *set {
		mac := hmac.New(sha256.New, k)
		mac.Write(body)
		if hmac.Equal(sig, mac.Sum(nil)) {
			matched = true
		}
	}
	return matched
}
```

