`auth/oidc_verify.go`
```go
package auth

import (
	"crypto/subtle"
	"errors"
	"github.com/golang-jwt/jwt/v5"
)

const bclEventURI = "http://schemas.openid.net/event/backchannel-logout"

func VerifyIDToken(raw, expectedNonce string, kf jwt.Keyfunc, iss, aud string) (jwt.MapClaims, error) {
	if expectedNonce == "" {
		return nil, errors.New("missing expected nonce")
	}
	claims := jwt.MapClaims{}
	tok, err := jwt.ParseWithClaims(
		raw,
		claims,
		kf,
		jwt.WithValidMethods([]string{"RS256"}),
		jwt.WithIssuer(iss),
		jwt.WithAudience(aud),
		jwt.WithExpirationRequired(),
	)
	if err != nil || !tok.Valid {
		return nil, errors.New("invalid id_token")
	}
	if _, hasEvents := claims["events"]; hasEvents {
		return nil, errors.New("logout_token rejected as id_token")
	}
	gotNonce, _ := claims["nonce"].(string)
	if subtle.ConstantTimeCompare([]byte(gotNonce), []byte(expectedNonce)) != 1 {
		return nil, errors.New("id_token nonce mismatch")
	}
	return claims, nil
}

func VerifyLogoutToken(raw string, kf jwt.Keyfunc, iss, aud string) (jwt.MapClaims, error) {
	claims := jwt.MapClaims{}
	tok, err := jwt.ParseWithClaims(
		raw,
		claims,
		kf,
		jwt.WithValidMethods([]string{"RS256"}),
		jwt.WithIssuer(iss),
		jwt.WithAudience(aud),
		jwt.WithIssuedAt(),
	)
	if err != nil || !tok.Valid {
		return nil, errors.New("invalid logout_token")
	}
	if _, hasNonce := claims["nonce"]; hasNonce {
		return nil, errors.New("logout_token must not contain nonce")
	}
	evts, ok := claims["events"].(map[string]any)
	if !ok {
		return nil, errors.New("missing events claim")
	}
	if _, hasBCL := evts[bclEventURI].(map[string]any); !hasBCL {
		return nil, errors.New("missing backchannel-logout event")
	}
	jti, _ := claims["jti"].(string)
	if jti == "" {
		return nil, errors.New("missing logout jti")
	}
	return claims, nil
}
