export interface DelegationTarget {
  audience: string;
  resource: string;
  scope: string;
}

export async function exchangeForDownstreamToken(
  subjectToken: string,
  target: DelegationTarget
): Promise<string> {
  const clientId = process.env.ORCHESTRATOR_CLIENT_ID ?? "";
  const clientSecret = process.env.ORCHESTRATOR_CLIENT_SECRET ?? "";
  const basic = Buffer.from(`${clientId}:${clientSecret}`).toString("base64");

  const resp = await fetch("https://idp.acme.io/oauth/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: `Basic ${basic}`,
    },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:token-exchange",
      subject_token: subjectToken,
      subject_token_type: "urn:ietf:params:oauth:token-type:access_token",
      audience: target.audience,
      resource: target.resource,
      scope: target.scope,
    }),
  });
  if (!resp.ok) {
    throw new Error(`Token exchange rejected: ${resp.status}`);
  }
  const data = (await resp.json()) as { access_token?: string };
  if (!data.access_token) {
    throw new Error("Missing exchanged access_token");
  }
  return data.access_token;
}
