import { Router } from "express";
import { jwtVerify, createRemoteJWKSet } from "jose";

export const billingRouter = Router();
const jwks = createRemoteJWKSet(new URL("https://idp.acme.io/.well-known/jwks.json"));

billingRouter.post("/v1/billing/charge", async (req, res) => {
  const authHdr = req.header("authorization") ?? "";
  if (!authHdr.startsWith("Bearer ")) {
    res.status(401).json({ error: "missing bearer" });
    return;
  }
  try {
    const raw = authHdr.slice("Bearer ".length).trim();
    const { payload } = await jwtVerify(raw, jwks, {
      issuer: "https://idp.acme.io",
      audience: "mcp-billing",
      algorithms: ["RS256", "ES256"],
    });
    const audList = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
    const scopes = String(payload.scope ?? "").split(" ");
    if (audList.length !== 1 || audList[0] !== "mcp-billing" || !scopes.includes("billing:write")) {
      res.status(403).json({ error: "forbidden token audience or scope" });
      return;
    }
    await chargeAccount(String(payload.sub));
    res.json({ charged: true });
  } catch {
    res.status(401).json({ error: "invalid token" });
  }
});
