use aws_sdk_s3::{presigning::PresigningConfig, Client};

fn validate_flat_doc_name(name: &str) -> Result<&str> {
    if name.is_empty()
        || name.len() > 128
        || name == "."
        || name.contains("..")
        || name.contains('/')
        || name.contains('\\')
        || name.contains('%')
        || !name
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b'_'))
