    bucket: &str,
    principal: &crate::auth::tenant::TenantPrincipal,
    doc_name: &str,
) -> Result<String> {
    let safe_doc = validate_flat_doc_name(doc_name)?;
    let expected_prefix = format!("tenants/{}/docs/", principal.id());
    let key = format!("{}{}", expected_prefix, safe_doc);
    if !key.starts_with(&expected_prefix) {
