`src/cli/loopback.rs`
```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use anyhow::{bail, Result};
use axum::{extract::Query, http::StatusCode, routing::get, Router};
use tokio::net::TcpListener;
use tokio::sync::oneshot;
use tokio::time::timeout;
use crate::cli::pkce::constant_time_state_eq;

pub async fn start_loopback_listener(
    expected_state: String,
) -> Result<(u16, tokio::task::JoinHandle<Result<String>>)> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let port = listener.local_addr()?.port();

    let (code_tx, code_rx) = oneshot::channel::<Result<String>>();
    let (stop_tx, stop_rx) = oneshot::channel::<()>();
    let slot = Arc::new(Mutex::new(Some((code_tx, stop_tx))));

    let app = Router::new().route(
        "/callback",
        get(move |Query(params): Query<HashMap<String, String>>| {
            let slot = slot.clone();
            let exp_state = expected_state.clone();
            async move {
                let got_state = params.get("state").map(String::as_str).unwrap_or("");
                if !constant_time_state_eq(&exp_state, got_state) {
                    return (StatusCode::BAD_REQUEST, "State mismatch; login aborted.");
                }
                let Some((c_tx, s_tx)) = slot.lock().unwrap().take() else {
                    return (StatusCode::CONFLICT, "Callback already processed.");
                };
                let _ = s_tx.send(());
                if let Some(code) = params.get("code") {
                    let _ = c_tx.send(Ok(code.clone()));
                    (StatusCode::OK, "Login complete. You may close this tab.")
                } else {
                    let _ = c_tx.send(Err(anyhow::anyhow!("authorization denied by provider")));
                    (StatusCode::BAD_REQUEST, "Login failed at identity provider.")
                }
            }
        }),
    );

    let wait_handle = tokio::spawn(async move {
        let srv = axum::serve(listener, app).with_graceful_shutdown(async {
            let _ = stop_rx.await;
        });
        tokio::spawn(async move {
            let _ = srv.await;
        });
        match timeout(Duration::from_secs(180), code_rx).await {
            Ok(Ok(res)) => res,
            Ok(Err(_)) => bail!("callback channel closed"),
            Err(_) => bail!("timed out waiting for OAuth callback"),
        }
    });

    Ok((port, wait_handle))
}
```

