  const item: PendingApproval = {
    id,
    orgId,
    tool,
    frozenArgsJson,
    argsSha256: canonicalHash(tool, frozenArgsJson),
    status: "pending",
    expiresAtMs: Date.now() + 15 * 60_000,
  };
  store.set(id, item);
  return item;
