package session

import (
	"crypto/cipher"
	"crypto/rand"
	"encoding/json"
	"errors"
	"io"
	"time"
)

type payload struct {
	Sub string `json:"sub"`
	Exp int64  `json:"exp"`
}

func buildAAD(host string) []byte {
	return []byte("__Host-portal_sid:v1:" + host)
}

func SealSession(aead cipher.AEAD, host, userID string, ttl time.Duration) ([]byte, error) {
	nonce := make([]byte, aead.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	body, err := json.Marshal(payload{Sub: userID, Exp: time.Now().Add(ttl).Unix()})
	if err != nil {
		return nil, err
	}
	return aead.Seal(nonce, nonce, body, buildAAD(host)), nil
}

func OpenSession(aead cipher.AEAD, host string, raw []byte) (string, error) {
	ns := aead.NonceSize()
	if len(raw) < ns+aead.Overhead()+2 {
		return "", errors.New("short session token")
	}
	pt, err := aead.Open(nil, raw[:ns], raw[ns:], buildAAD(host))
	if err != nil {
		return "", err
	}
	var p payload
	if err := json.Unmarshal(pt, &p); err != nil || p.Sub == "" || time.Now().Unix() >= p.Exp {
		return "", errors.New("expired or malformed session")
	}
	return p.Sub, nil
}
