const CANONICAL_BASE = "https://app.acme.io";

export function sanitizeReturnPath(nextParam: string | null | undefined): string {
  if (!nextParam || typeof nextParam !== "string") {
    return "/dashboard";
  }
  const trimmed = nextParam.trim();
  if (
    !trimmed.startsWith("/") ||
    trimmed.startsWith("//") ||
    trimmed.includes("\\") ||
    /[\u0000-\u001F\u007F]/.test(trimmed)
  ) {
    return "/dashboard";
  }
  try {
    const resolved = new URL(trimmed, CANONICAL_BASE);
    if (resolved.origin !== CANONICAL_BASE) {
      return "/dashboard";
    }
    return `${resolved.pathname}${resolved.search}${resolved.hash}`;
  } catch {
    return "/dashboard";
  }
}
