import { WebSocketServer } from "ws";
import { verifyWsJwt, WsPrincipal } from "./authUpgrade";
import { joinOrgRoom, leaveOrgRoom } from "./roomManager";

export function attachWs(wss: WebSocketServer, secret: Uint8Array) {
  wss.on("connection", async (socket, req) => {
    let principal: WsPrincipal;
    try {
      const proto = req.headers["sec-websocket-protocol"] ?? "";
      const bearer = proto.startsWith("bearer.") ? proto.slice("bearer.".length) : "";
      principal = await verifyWsJwt(bearer, secret);
    } catch {
      socket.close(4401, "unauthorized");
      return;
    }

    let expiryTimer: NodeJS.Timeout | undefined;
    const armExpiry = (expMs: number) => {
      if (expiryTimer) clearTimeout(expiryTimer);
      const ttl = Math.max(0, expMs - Date.now());
      expiryTimer = setTimeout(() => socket.close(4401, "token expired"), ttl);
    };
    armExpiry(principal.expMs);
    joinOrgRoom(principal.orgId, socket);

    socket.on("message", async (raw) => {
      try {
        const msg = JSON.parse(raw.toString("utf8")) as { action?: string; token?: string };
        if (msg.action === "reauth" && typeof msg.token === "string") {
          const refreshed = await verifyWsJwt(msg.token, secret);
          if (refreshed.userId !== principal.userId || refreshed.orgId !== principal.orgId) {
            socket.close(4403, "identity mismatch");
            return;
          }
          principal = refreshed;
          armExpiry(principal.expMs);
        }
      } catch {
        socket.close(4400, "bad frame");
      }
    });

    socket.on("close", () => {
      if (expiryTimer) clearTimeout(expiryTimer);
      leaveOrgRoom(principal.orgId, socket);
    });
  });
}
```

