use anyhow::{bail, Result};

pub const HEADER_LEN: usize = 34;
pub const CURRENT_VERSION: u8 = 1;
pub const MIN_PBKDF2_ITERS: u32 = 210_000;
pub const MAX_PBKDF2_ITERS: u32 = 1_000_000;

pub struct VaultHeader {
    pub version: u8,
    pub flags: u8,
    pub pbkdf2_iters: u32,
    pub salt: [u8; 16],
    pub nonce: [u8; 12],
    pub raw_aad: [u8; HEADER_LEN],
}

impl VaultHeader {
    pub fn parse(raw: &[u8; HEADER_LEN]) -> Result<Self> {
        let version = raw[0];
        if version != CURRENT_VERSION {
            bail!("unsupported vault version: {}", version);
        }
        let iters = u32::from_be_bytes([raw[2], raw[3], raw[4], raw[5]]);
