use tonic::{Request, Status};
use x509_parser::extensions::GeneralName;
use x509_parser::prelude::FromDer;

const EXPECTED_SPIFFE: &str = "spiffe://acme.internal/ns/prod/sa/vault-admin";

pub fn require_vault_admin(mut req: Request<()>) -> Result<Request<()>, Status> {
    req.metadata_mut().remove("x-spiffe-id");
    let certs = req
        .peer_certs()
        .ok_or_else(|| Status::unauthenticated("missing mTLS peer certificate"))?;
    let leaf_der = certs
        .first()
        .ok_or_else(|| Status::unauthenticated("empty peer certificate chain"))?;

    let (_, parsed) = x509_parser::certificate::X509Certificate::from_der(leaf_der.as_ref())
        .map_err(|_| Status::unauthenticated("malformed X.509 leaf"))?;
    let san_ext = parsed
        .subject_alternative_name()
        .map_err(|_| Status::unauthenticated("invalid SAN extension"))?
        .ok_or_else(|| Status::unauthenticated("missing SAN extension"))?;

    let authorized = san_ext.value.general_names.iter().any(|gn| match gn {
        GeneralName::URI(uri) => *uri == EXPECTED_SPIFFE,
        _ => false,
    });
    if !authorized {
        return Err(Status::permission_denied("peer SPIFFE URI not authorized"));
    }
    Ok(req)
}
