package mcp

import (
	"context"
	"errors"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

var lineSpecRe = regexp.MustCompile(`^[1-9][0-9]{0,5},[1-9][0-9]{0,5}$`)

func GitBlameRange(ctx context.Context, repoDir, lineSpec, relFile string) ([]byte, error) {
	if !lineSpecRe.MatchString(lineSpec) {
		return nil, errors.New("invalid line range")
	}
	if filepath.IsAbs(relFile) || strings.HasPrefix(relFile, "-") {
		return nil, errors.New("invalid file path")
	}
	cleanRepo, err := filepath.EvalSymlinks(repoDir)
	if err != nil {
		return nil, err
	}
	target, err := filepath.EvalSymlinks(filepath.Join(cleanRepo, relFile))
	if err != nil || !strings.HasPrefix(target, cleanRepo+string(filepath.Separator)) {
		return nil, errors.New("file escapes repository")
	}
	normRel, err := filepath.Rel(cleanRepo, target)
	if err != nil {
		return nil, err
	}
	cmd := exec.CommandContext(ctx, "git", "blame", "-L", lineSpec, "--", normRel)
	cmd.Dir = cleanRepo
	return cmd.Output()
}
