`oauth/token_endpoint.go`
```go
package oauth

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"regexp"
	"time"
)

var pkceVerifierRe = regexp.MustCompile(`^[A-Za-z0-9\._~-]{43,128}$`)

func ExchangeAuthCode(rec AuthCodeRecord, clientID, redirectURI, verifier string) (string, error) {
	if time.Now().After(rec.ExpiresAt) {
		return "", errors.New("authorization code expired")
	}
	if rec.ClientID == "" || rec.ClientID != clientID || rec.RedirectURI != redirectURI {
		return "", errors.New("client or redirect mismatch")
	}
	if rec.CodeChallenge == "" || rec.CodeChallengeMethod != "S256" {
		return "", errors.New("pkce S256 challenge required")
	}
	if !pkceVerifierRe.MatchString(verifier) {
		return "", errors.New("invalid or missing code_verifier")
	}
	sum := sha256.Sum256([]byte(verifier))
	computed := base64.RawURLEncoding.EncodeToString(sum[:])
	if subtle.ConstantTimeCompare([]byte(computed), []byte(rec.CodeChallenge)) != 1 {
		return "", errors.New("pkce verification failed")
	}
	return issueAccessToken(rec.Subject), nil
}
