interface BucketEntry {
  count: number;
  resetAt: number;
}

const MAX_LOCAL_KEYS = 10_000;
const localCounts = new Map<string, BucketEntry>();

export function allowLocal(bucketHash: string, limit: number): boolean {
  const now = Date.now();
  const existing = localCounts.get(bucketHash);
  if (!existing || now > existing.resetAt) {
    if (localCounts.size >= MAX_LOCAL_KEYS) {
      for (const [k, v] of localCounts) {
        if (now > v.resetAt) localCounts.delete(k);
        if (localCounts.size < MAX_LOCAL_KEYS) break;
      }
      if (localCounts.size >= MAX_LOCAL_KEYS) return false;
    }
    localCounts.set(bucketHash, { count: 1, resetAt: now + 60_000 });
    return true;
  }
  existing.count += 1;
  return existing.count <= limit;
}
