import crypto from "node:crypto";
import { Request, Response, NextFunction } from "express";
import { redis } from "../lib/redis";
import { allowLocal } from "./memoryFallback";

const INCR_EXPIRE_LUA = `
local c = redis.call('INCR', KEYS[1])
if c == 1 then
  redis.call('EXPIRE', KEYS[1], tonumber(ARGV[1]))
end
return c
`;

function deriveBucketHash(rawKey: string): string {
  const salt = process.env.RL_HASH_SALT ?? "acme-rl-v2";
  return crypto.createHmac("sha256", salt).update(rawKey).digest("hex").slice(0, 32);
}

export async function apiKeyRateLimit(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  const rawKey = req.header("x-api-key");
  const identifier = rawKey && rawKey.length <= 256 ? `key:${rawKey}` : `ip:${req.ip}`;
  const bucketHash = deriveBucketHash(identifier);
  try {
    const n = Number(await redis.eval(INCR_EXPIRE_LUA, 1, `rl:v2:${bucketHash}`, "60"));
    if (n > 60) {
      res.status(429).json({ error: "rate limited" });
      return;
    }
  } catch {
    if (!allowLocal(bucketHash, 60)) {
      res.status(429).json({ error: "rate limited" });
      return;
    }
  }
  next();
}
