`src/mcp/urlCheck.ts`
```typescript
import dns from "node:dns/promises";
import ipaddr from "ipaddr.js";

export function isPublicUnicastIp(rawIp: string): boolean {
  if (!ipaddr.isValid(rawIp)) return false;
  const parsed = ipaddr.process(rawIp);
  return parsed.range() === "unicast";
}

export async function resolveAndVerifyHost(rawUrl: string): Promise<{ url: URL; pinnedIp: string; family: 4 | 6 }> {
  const u = new URL(rawUrl);
  if (u.protocol !== "https:" && u.protocol !== "http:") {
    throw new Error("Unsupported URL protocol");
  }
  if (u.username || u.password) {
    throw new Error("Credentials in URL are forbidden");
  }
  const bareHost = u.hostname.replace(/^\[|\]$/g, "");
  if (ipaddr.isValid(bareHost)) {
    if (!isPublicUnicastIp(bareHost)) {
      throw new Error("Blocked non-unicast IP literal");
    }
    const parsed = ipaddr.parse(bareHost);
    return { url: u, pinnedIp: bareHost, family: parsed.kind() === "ipv6" ? 6 : 4 };
  }
  const records = await dns.lookup(bareHost, { all: true, verbatim: true });
  if (records.length === 0) {
    throw new Error("DNS lookup returned no records");
  }
  for (const rec of records) {
    if (!isPublicUnicastIp(rec.address)) {
      throw new Error(`Blocked resolved non-unicast IP: ${rec.address}`);
    }
  }
  return {
    url: u,
    pinnedIp: records[0].address,
    family: records[0].family === 6 ? 6 : 4,
  };
}
