import { Agent } from "undici";
import { resolveAndVerifyHost } from "./urlCheck";

const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

export async function fetchImageBytes(imageUrl: string): Promise<Buffer> {
  const { url, pinnedIp, family } = await resolveAndVerifyHost(imageUrl);
  const dispatcher = new Agent({
    connect: {
      timeout: 5000,
      lookup: (_hostname, _opts, cb) => cb(null, [{ address: pinnedIp, family }]),
    },
  });

  try {
    const resp = await fetch(url, {
      redirect: "error",
      signal: AbortSignal.timeout(8000),
      // @ts-expect-error Node global fetch accepts undici dispatcher
      dispatcher,
    });
    if (!resp.ok || !resp.body) {
      throw new Error(`Image fetch failed: ${resp.status}`);
    }
    const reader = resp.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_IMAGE_BYTES) {
        await reader.cancel();
        throw new Error("Image exceeds 5 MiB limit");
      }
      chunks.push(value);
    }
    return Buffer.concat(chunks);
  } finally {
    await dispatcher.close();
  }
}
