use anyhow::{bail, Result};

pub fn canonicalize_http_path(raw_path: &str) -> Result<String> {
    let lower_raw = raw_path.to_ascii_lowercase();
    if lower_raw.contains("%2f") || lower_raw.contains("%5c") || lower_raw.contains("%00") {
        bail!("encoded path separators or null bytes rejected");
    }
    let decoded = percent_encoding::percent_decode_str(raw_path)
        .decode_utf8()
        .map_err(|_| anyhow::anyhow!("invalid utf-8 in path"))?;
    if decoded.contains('\\') || decoded.contains('\0') {
        bail!("invalid path characters");
    }

    let mut stack: Vec<&str> = Vec::new();
    for seg in decoded.split('/') {
        match seg {
            "" | "." => {}
            ".." => {
                stack.pop();
            }
            s => stack.push(s),
        }
    }
    Ok(format!("/{}", stack.join("/")))
}

pub fn requires_admin_mtls(canonical_path: &str) -> bool {
    let lower = canonical_path.to_ascii_lowercase();
    lower == "/v1/admin" || lower.starts_with("/v1/admin/")
}
