use axum::http::{StatusCode, Uri};
use axum::{extract::Request, response::Response};
use crate::proxy::acl::{canonicalize_http_path, requires_admin_mtls};

pub async fn edge_proxy(mut req: Request, has_mtls: bool) -> Result<Response, StatusCode> {
    let canon_path = canonicalize_http_path(req.uri().path()).map_err(|_| StatusCode::BAD_REQUEST)?;
    if requires_admin_mtls(&canon_path) && !has_mtls {
        return Err(StatusCode::FORBIDDEN);
    }

    let new_pq = match req.uri().query() {
        Some(q) => format!("{}?{}", canon_path, q),
        None => canon_path,
    };
    let mut parts = req.uri().clone().into_parts();
    parts.path_and_query = Some(new_pq.parse().map_err(|_| StatusCode::BAD_REQUEST)?);
    *req.uri_mut() = Uri::from_parts(parts).map_err(|_| StatusCode::BAD_REQUEST)?;

    forward_raw_uri_to_upstream(req).await
}
