use std::time::{Duration, Instant};
use tokio::sync::Mutex;
use crate::oauth::idp_client::TokenResponse;

pub struct M2mCache {
    inner: Mutex<Option<(String, Instant)>>,
}

impl M2mCache {
    pub fn new() -> Self {
        Self {
            inner: Mutex::new(None),
        }
    }

    fn compute_safe_ttl(expires_in: u64) -> Duration {
        let capped = expires_in.min(86_400);
        let leeway = if capped > 60 { 30 } else { capped / 3 };
        Duration::from_secs(capped.saturating_sub(leeway))
    }

    pub async fn invalidate(&self, stale_token: &str) {
        let mut guard = self.inner.lock().await;
        if let Some((ref current, _)) = *guard {
            if current == stale_token {
                *guard = None;
            }
        }
    }

    pub async fn get_token<F, Fut>(&self, fetch: F) -> anyhow::Result<String>
    where
        F: FnOnce() -> Fut,
        Fut: std::future::Future<Output = anyhow::Result<TokenResponse>>,
    {
        let mut guard = self.inner.lock().await;
        let now = Instant::now();
        if let Some((ref tok, valid_until)) = *guard {
            if now < valid_until {
                return Ok(tok.clone());
            }
        }
        let resp = fetch().await?;
        let ttl = Self::compute_safe_ttl(resp.expires_in);
        if !ttl.is_zero() {
            *guard = Some((resp.access_token.clone(), Instant::now() + ttl));
        } else {
            *guard = None;
        }
        Ok(resp.access_token)
    }
}
```

`src/mcp/outbound.rs`
```rust
use reqwest::StatusCode;
use crate::oauth::m2m_cache::M2mCache;

pub async fn send_authenticated_rpc(
    http: &reqwest::Client,
    cache: &M2mCache,
    url: &str,
) -> anyhow::Result<u16> {
    let tok = cache.get_token(request_client_credentials).await?;
    let resp = http.post(url).bearer_auth(&tok).send().await?;
    if resp.status() == StatusCode::UNAUTHORIZED {
        cache.invalidate(&tok).await;
        let fresh_tok = cache.get_token(request_client_credentials).await?;
        let retry = http.post(url).bearer_auth(&fresh_tok).send().await?;
        return Ok(retry.status().as_u16());
    }
    Ok(resp.status().as_u16())
}
```

