```go
package ingest

import (
	"bytes"
	"context"
	"io"
	"net/http"
)

type rawBodyCtxKey struct{}

const maxIngestBytes = 2 << 20

func RawBodyCaptureMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = http.MaxBytesReader(w, r.Body, maxIngestBytes)
		raw, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "payload read error or too large", http.StatusRequestEntityTooLarge)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(raw))
		ctx := context.WithValue(r.Context(), rawBodyCtxKey{}, raw)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func ExactWireBody(r *http.Request) ([]byte, bool) {
	b, ok := r.Context().Value(rawBodyCtxKey{}).([]byte)
	return b, ok
}
