func VerifyRawHMAC(secret, exactWireBody []byte, hexSig string) bool {
	if len(secret) < 32 || len(hexSig) != 64 {
		return false
	}
	sig, err := hex.DecodeString(hexSig)
	if err != nil {
		return false
	}
	mac := hmac.New(sha256.New, secret)
