import { prisma } from "../db/client";

export type ClaimOutcome =
  | { status: "rotated"; userId: string }
  | { status: "replayed_or_invalid" };

export async function atomicClaimAndRotate(
  oldHash: string,
  newHash: string,
  ttlMs: number
): Promise<ClaimOutcome> {
  return prisma.$transaction(async (tx) => {
    const now = new Date();
    const existing = await tx.refreshToken.findUnique({ where: { tokenHash: oldHash } });
    if (!existing || existing.expiresAt <= now) {
      return { status: "replayed_or_invalid" };
    }

    const claimed = await tx.refreshToken.updateMany({
      where: {
        tokenHash: oldHash,
        usedAt: null,
        expiresAt: { gt: now },
      },
      data: { usedAt: now },
    });

    if (claimed.count !== 1) {
      await tx.refreshToken.deleteMany({ where: { familyId: existing.familyId } });
      return { status: "replayed_or_invalid" };
    }

    await tx.refreshToken.create({
      data: {
        tokenHash: newHash,
        userId: existing.userId,
        familyId: existing.familyId,
        expiresAt: new Date(now.getTime() + ttlMs),
      },
    });
    return { status: "rotated", userId: existing.userId };
  });
}
