import { atomicClaimAndRotate } from "./refreshRepo";

const REFRESH_TTL_MS = 14 * 24 * 3600 * 1000;

export async function rotateToken(rawRefresh: string) {
  const oldHash = crypto.createHash("sha256").update(rawRefresh, "utf8").digest("hex");
  const nextRaw = crypto.randomBytes(32).toString("base64url");
  const nextHash = crypto.createHash("sha256").update(nextRaw, "utf8").digest("hex");

