use std::collections::HashSet;
use std::sync::Mutex;
use p256::ecdsa::VerifyingKey;
use sha2::{Digest, Sha256};

pub struct ReplayGuard {
    seen_messages: Mutex<HashSet<[u8; 32]>>,
}

impl ReplayGuard {
    pub fn new() -> Self {
        Self {
            seen_messages: Mutex::new(HashSet::new()),
        }
    }

    pub fn claim_authenticated_message(&self, vk: &VerifyingKey, cmd_bytes: &[u8]) -> bool {
        let mut hasher = Sha256::new();
        hasher.update(b"acme-cmd-dedup:v1:");
        hasher.update(vk.to_encoded_point(true).as_bytes());
        hasher.update(cmd_bytes);
        let digest: [u8; 32] = hasher.finalize().into();
        self.seen_messages
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .insert(digest)
    }
}
