	}
	peer, err := curve.NewPublicKey(peerBytes)
	if err != nil {
		return nil, nil, err
	}
	rawShared, err := priv.ECDH(peer)
	if err != nil {
		return nil, nil, err
	}
	ephPub := priv.PublicKey().Bytes()
	info := make([]byte, 0, 24+len(ephPub)+len(peerBytes))
	info = append(info, "acme-kb-x25519-hkdf-v1:"...)
	info = append(info, ephPub...)
	info = append(info, peerBytes...)

	r := hkdf.New(sha256.New, rawShared, nil, info)
	derived := make([]byte, 32)
	if _, err := io.ReadFull(r, derived); err != nil {
		return nil, nil, err
	}
	return derived, ephPub, nil
}
