`src/uploads/multipart.ts`
```typescript
import crypto from "node:crypto";
import fs from "node:fs";
import fsp from "node:fs/promises";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import busboy from "busboy";
import { Request } from "express";

export class FileTooLargeError extends Error {}

export function receiveSingleFile(req: Request, tmpDest: string): Promise<string> {
  return new Promise((resolve, reject) => {
    let settled = false;
    let fileSeen = false;
    const fail = (err: Error) => {
      if (settled) return;
      settled = true;
      req.unpipe(bb);
      void fsp.unlink(tmpDest).catch(() => undefined);
      reject(err);
    };

    const bb = busboy({
      headers: req.headers,
      limits: { files: 1, fileSize: 10 * 1024 * 1024 },
    });

    req.on("aborted", () => fail(new Error("Client aborted upload")));

    bb.on("file", (_name, fileStream) => {
      fileSeen = true;
      let truncated = false;
      const hasher = crypto.createHash("sha256");
      const tap = new Transform({
        transform(chunk, _enc, cb) {
          hasher.update(chunk);
          cb(null, chunk);
        },
      });

      fileStream.on("limit", () => {
        truncated = true;
        fileStream.destroy(new FileTooLargeError("File exceeds 10 MiB limit"));
      });

      const ws = fs.createWriteStream(tmpDest, { mode: 0o600, flags: "wx" });
      void pipeline(fileStream, tap, ws)
        .then(() => {
          if (truncated || req.aborted) {
            fail(new FileTooLargeError("Truncated or aborted upload"));
            return;
          }
          if (!settled) {
            settled = true;
            resolve(hasher.digest("hex"));
          }
        })
        .catch((err) => fail(err instanceof Error ? err : new Error(String(err))));
    });

    bb.on("close", () => {
      if (!fileSeen) fail(new Error("No file part in multipart payload"));
    });
    bb.on("error", (err) => fail(err instanceof Error ? err : new Error(String(err))));
    req.pipe(bb);
  });
}
```

`src/uploads/verify.ts`
```typescript
import crypto from "node:crypto";
import fsp from "node:fs/promises";

export async function promoteVerifiedUpload(
  tmpDest: string,
  finalDest: string,
  actualSha256: string,
  expectedSha256: string
): Promise<void> {
  const a = Buffer.from(actualSha256, "hex");
  const b = Buffer.from(expectedSha256, "hex");
  if (a.byteLength !== 32 || b.byteLength !== 32 || !crypto.timingSafeEqual(a, b)) {
    await fsp.unlink(tmpDest).catch(() => undefined);
    throw new Error("SHA-256 digest mismatch");
  }
  await fsp.rename(tmpDest, finalDest);
}
```

