use hmac::{Hmac, Mac};
use sha2::Sha256;

pub fn parse_sig_header(header_hex: &str) -> Option<[u8; 32]> {
    let trimmed = header_hex.strip_prefix("sha256=").unwrap_or(header_hex);
    if trimmed.len() != 64 {
        return None;
    }
    let mut out = [0u8; 32];
    hex::decode_to_slice(trimmed, &mut out).ok()?;
    Some(out)
}

pub fn check_hmac_tag(secret: &[u8], payload: &[u8], tag: &[u8; 32]) -> bool {
    if secret.len() < 32 {
        return false;
    }
    let Ok(mut mac) = Hmac::<Sha256>::new_from_slice(secret) else {
        return false;
    };
    mac.update(payload);
    mac.verify_slice(tag).is_ok()
}
