use anyhow::{anyhow, bail, Result};
use jsonwebtoken::{decode, decode_header, Algorithm, DecodingKey, Validation};
use serde::Deserialize;
use crate::jwt::header_jku::fetch_pinned_jwks;

#[derive(Deserialize)]
pub struct TokenClaims {
    pub sub: String,
    pub role: String,
}

pub struct PinnedVerifier {
    pub http: reqwest::Client,
    pub jwks_url: String,
    pub issuer: String,
    pub audience: String,
}

impl PinnedVerifier {
    pub async fn verify_jwt(&self, token: &str) -> Result<TokenClaims> {
        if token.len() > 8192 {
            bail!("oversized jwt");
        }
        let hdr = decode_header(token)?;
        if hdr.alg != Algorithm::RS256 {
            bail!("disallowed jwt alg");
        }
        if hdr.jku.is_some() || hdr.jwk.is_some() || hdr.x5u.is_some() {
            bail!("embedded key headers (jku/jwk/x5u) are forbidden");
        }
        let kid = hdr.kid.ok_or_else(|| anyhow!("missing kid"))?;
        let set = fetch_pinned_jwks(&self.http, &self.jwks_url).await?;
        let jwk = set.find(&kid).ok_or_else(|| anyhow!("kid not found"))?;
        let key = DecodingKey::from_jwk(jwk)?;

        let mut val = Validation::new(Algorithm::RS256);
        val.set_issuer(&[&self.issuer]);
        val.set_audience(&[&self.audience]);
        Ok(decode::<TokenClaims>(token, &key, &val)?.claims)
    }
}
