	writeLenPrefixed(h, e.Target)
	writeLenPrefixed(h, e.Nonce)
	var expBuf [8]byte
	binary.BigEndian.PutUint64(expBuf[:], uint64(e.ExpiresAt))
	_, _ = h.Write(expBuf[:])

	var out [32]byte
	copy(out[:], h.Sum(nil))
	return out
