import crypto from "node:crypto";

const VERIFIER_RE = /^[A-Za-z0-9._~-]{43,128}$/;

export function verifyPkceS256(verifier: string, storedChallenge: string): boolean {
  if (!VERIFIER_RE.test(verifier) || !storedChallenge) {
