import crypto from "node:crypto";

export function encryptRecord(key: Buffer, jsonText: string): string {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv("aes-256-ctr", key, iv);
  const ct = Buffer.concat([cipher.update(jsonText, "utf8"), cipher.final()]);
  return `${iv.toString("hex")}:${ct.toString("hex")}`;
}

export function decryptRecord(key: Buffer, stored: string): string {
  const [ivHex, ctHex] = stored.split(":");
  const decipher = crypto.createDecipheriv("aes-256-ctr", key, Buffer.from(ivHex, "hex"));
  const pt = Buffer.concat([decipher.update(Buffer.from(ctHex, "hex")), decipher.final()]);
  return pt.toString("utf8");
}
