import crypto from "node:crypto";

export function encryptRecord(key: Buffer, aadContext: string, jsonText: string): string {
  if (key.byteLength !== 32 || !aadContext) {
    throw new Error("Invalid 32-byte vault key or empty AAD");
  }
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv, { authTagLength: 16 });
  cipher.setAAD(Buffer.from(`integration:v2:${aadContext}`, "utf8"));
  const ct = Buffer.concat([cipher.update(jsonText, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `v2:${iv.toString("hex")}:${tag.toString("hex")}:${ct.toString("hex")}`;
}

export function decryptRecord(key: Buffer, aadContext: string, stored: string): string {
  if (key.byteLength !== 32 || !aadContext) {
    throw new Error("Invalid 32-byte vault key or empty AAD");
  }
  const parts = stored.split(":");
  if (parts.length !== 4 || parts[0] !== "v2") {
    throw new Error("Unsupported or malformed ciphertext format");
  }
  const iv = Buffer.from(parts[1], "hex");
  const tag = Buffer.from(parts[2], "hex");
  const ct = Buffer.from(parts[3], "hex");
  if (iv.byteLength !== 12 || tag.byteLength !== 16) {
    throw new Error("Invalid IV or authentication tag length");
  }
  const decipher = crypto.createDecipheriv("aes-256-gcm", key, iv, { authTagLength: 16 });
  decipher.setAAD(Buffer.from(`integration:v2:${aadContext}`, "utf8"));
  decipher.setAuthTag(tag);
  const pt = Buffer.concat([decipher.update(ct), decipher.final()]);
  return pt.toString("utf8");
}
