pub struct SessionTable {
    map: RwLock<HashMap<String, ActiveSession>>,
}

impl SessionTable {
    pub fn new() -> Self {
        Self {
            map: RwLock::new(HashMap::new()),
        }
    }

    pub fn is_active(&self, sid: &str) -> bool {
        let guard = self.map.read().unwrap_or_else(|e| e.into_inner());
        guard
            .get(sid)
            .map(|s| s.expires_at > Instant::now())
            .unwrap_or(false)
    }

