        let now = Instant::now();
        let mut guard = self.map.write().unwrap_or_else(|e| e.into_inner());
        let mut removed = Vec::new();
        guard.retain(|_, sess| {
            if sess.expires_at <= now {
                removed.push(sess.clone());
                false
            } else {
                true
            }
        });
        removed
    }
}
