`auth/local_keys.go`
```go
package auth

import (
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var safeKidRe = regexp.MustCompile(`^[a-zA-Z0-9_-]{1,64}$`)

func LoadKeyByID(keyDir, kid string) ([]byte, error) {
	if !safeKidRe.MatchString(kid) {
		return nil, errors.New("invalid kid format")
	}
	canonDir, err := filepath.EvalSymlinks(keyDir)
	if err != nil {
		return nil, err
	}
	candidate := filepath.Join(canonDir, kid+".key")
	resolved, err := filepath.EvalSymlinks(candidate)
	if err != nil || !strings.HasPrefix(resolved, canonDir+string(filepath.Separator)) {
		return nil, errors.New("key path escaped directory")
	}
	info, err := os.Stat(resolved)
	if err != nil || !info.Mode().IsRegular() {
		return nil, errors.New("key is not a regular file")
	}
	keyBytes, err := os.ReadFile(resolved)
	if err != nil || len(keyBytes) < 32 {
		return nil, errors.New("HMAC key must be at least 32 bytes")
	}
	return keyBytes, nil
}
