`src/rag/job_tracker.rs`
```rust
use dashmap::DashMap;

pub struct JobState {
    pub parent_id: Option<String>,
    pub done_children: usize,
    pub completed: bool,
}

pub struct Tracker {
    jobs: DashMap<String, JobState>,
}

impl Tracker {
    pub fn new() -> Self {
        Self {
            jobs: DashMap::new(),
        }
    }

    pub fn mark_child_complete(&self, child_id: &str) {
        let parent_id = {
            let Some(mut child) = self.jobs.get_mut(child_id) else {
                return;
            };
            if child.completed {
                return;
            }
            child.completed = true;
            child.parent_id.clone()
        };

        if let Some(pid) = parent_id {
            if pid != child_id {
                if let Some(mut parent) = self.jobs.get_mut(&pid) {
                    parent.done_children += 1;
                }
            }
        }
    }

    pub fn is_completed(&self, id: &str) -> Option<bool> {
        self.jobs.get(id).map(|entry| entry.completed)
    }
}
