package ledger

import (
	"context"
	"database/sql"
	"errors"
)

func ExecuteTransfer(ctx context.Context, db *sql.DB, fromID, toID string, cents int64) error {
	if cents <= 0 || fromID == "" || toID == "" || fromID == toID {
		return errors.New("invalid transfer arguments")
	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	// Deterministic lock order prevents A<->B PostgreSQL row-lock deadlocks
	firstID, secondID := fromID, toID
	if firstID > secondID {
		firstID, secondID = secondID, firstID
	}
	var firstBal, secondBal int64
	if err := tx.QueryRowContext(ctx, `SELECT balance_cents FROM accounts WHERE id = $1 FOR UPDATE`, firstID).Scan(&firstBal); err != nil {
		return err
	}
	if err := tx.QueryRowContext(ctx, `SELECT balance_cents FROM accounts WHERE id = $1 FOR UPDATE`, secondID).Scan(&secondBal); err != nil {
		return err
	}
	senderBal := firstBal
	if fromID == secondID {
		senderBal = secondBal
	}
	if senderBal < cents {
