use std::io;
use tokio::io::{AsyncRead, AsyncReadExt};

pub const MAX_FRAME: usize = 1024 * 1024;

pub struct StatefulFrameReader<R> {
    reader: R,
    hdr: [u8; 4],
    hdr_filled: usize,
    body: Vec<u8>,
    body_filled: usize,
    in_body: bool,
}

impl<R: AsyncRead + Unpin> StatefulFrameReader<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            hdr: [0u8; 4],
            hdr_filled: 0,
            body: Vec::new(),
            body_filled: 0,
            in_body: false,
        }
    }

    /// Cancellation-safe: all partially read bytes live in `self`, never on the dropped future stack!
    pub async fn next_frame(&mut self) -> io::Result<Option<Vec<u8>>> {
        loop {
            if !self.in_body {
                while self.hdr_filled < 4 {
                    let n = self.reader.read(&mut self.hdr[self.hdr_filled..]).await?;
                    if n == 0 {
                        if self.hdr_filled == 0 {
                            return Ok(None);
                        }
                        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "truncated header"));
                    }
                    self.hdr_filled += n;
                }
                let frame_len = u32::from_be_bytes(self.hdr) as usize;
                if frame_len > MAX_FRAME {
                    return Err(io::Error::new(io::ErrorKind::InvalidData, "frame exceeds 1 MiB"));
                }
                self.hdr_filled = 0;
                self.body = vec![0u8; frame_len];
                self.body_filled = 0;
                self.in_body = true;
            }
            while self.body_filled < self.body.len() {
                let n = self.reader.read(&mut self.body[self.body_filled..]).await?;
                if n == 0 {
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "truncated body"));
                }
                self.body_filled += n;
            }
            self.in_body = false;
            self.body_filled = 0;
            return Ok(Some(std::mem::take(&mut self.body)));
        }
    }
}
