use std::io;
use nix::unistd::{setgroups, setresgid, setresuid, setuid, Gid, Uid};

pub fn drop_privileges_strict(target_uid: u32, target_gid: u32) -> io::Result<()> {
    if target_uid == 0 || target_gid == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "refusing to drop privileges to uid/gid 0",
        ));
    }
    let gid = Gid::from_raw(target_gid);
    let uid = Uid::from_raw(target_uid);

    // 1. Wipe inherited root supplementary groups while CAP_SETGID is still held
    setgroups(&[]).map_err(|e| io::Error::new(io::ErrorKind::PermissionDenied, e))?;
    // 2. Drop real, effective, and saved GID BEFORE dropping UID
    setresgid(gid, gid, gid).map_err(|e| io::Error::new(io::ErrorKind::PermissionDenied, e))?;
    // 3. Drop real, effective, and saved UID permanently
    setresuid(uid, uid, uid).map_err(|e| io::Error::new(io::ErrorKind::PermissionDenied, e))?;

    // 4. Verify privilege regain is impossible
    if setuid(Uid::from_raw(0)).is_ok() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "fatal: uid 0 remained regainable after setresuid",
        ));
    }
    Ok(())
}
